function encodeBatchRows(rows){if(!rows.some(row=>row.scopeNote))return rows.map(row=>row.title).join('\n');const quote=value=>'"'+String(value).replace(/"/g,'""')+'"';return '标题,适用范围与限制\n'+rows.map(row=>[row.title,row.scopeNote||''].map(quote).join(',')).join('\n')}
const uniqueTitles=raw=>[...new Map(titleRows(raw).map(t=>[norm(t),t])).values()];
function temporalTitle(d){const title=d.title.trim();if(!title)return'尚未命名的专题';if(d.freshness==='composed_at'&&!/^2026 年 9 月整理/.test(title))return`2026 年 9 月整理：${title}`;if(d.freshness==='annual'&&/^\d{4}$/.test(d['coverage-year'])&&d['coverage-note']?.trim()&&!/^\d{4} 版/.test(title))return`${d['coverage-year']} 版：${title}`;if(d.freshness==='as_of'&&/^\d{4}-\d{2}-\d{2}$/.test(d['coverage-date'])&&d['coverage-date']<=DEMO_DATE&&d['coverage-note']?.trim()&&!/^截至/.test(title))return`截至 ${d['coverage-date']}：${title}`;return title}
function publicTopic(t){if(!t.publicDraft||validIds(t.publicDraft.ids).length<2)return null;return{...t,...clone(t.publicDraft),ids:validIds(t.publicDraft.ids),title:t.publicDraft.displayTitle||temporalTitle(t.publicDraft),count:validIds(t.publicDraft.ids).length}}
function featuredTopics(){return state.topics.map(publicTopic).filter(Boolean)}
const candidate=t=>state.drafts[t.id]||newDraft(t.title,t.ids,t.layout);
const validLayout=value=>['default','guide','roundup'].includes(value)?value:'default';
const sourceTask=t=>state.tasks.find(task=>task.id===t.taskId||(!t.taskId&&task.name===t.source));
function draftIdentityQuery(){if(state.editorKind!=='new')return`id=${state.editId}`;const d=state.newDraft;state.previewTargets??={};state.previewTargets[d.previewKey]??={draft:d,topicId:null};return`id=new&draftKey=${encodeURIComponent(d.previewKey)}`}
function previewTarget(){return state.previewTargets?.[routeInfo().query.get('draftKey')]}
function previewDraft(){const q=routeInfo().query;const target=previewTarget();if(q.has('draftKey'))return target?target.topicId?getTopic(target.topicId)?state.drafts[target.topicId]:null:target.draft:null;const id=q.get('id');return id==='new'?state.newDraft:id?getTopic(Number(id))?state.drafts[Number(id)]:null:draft()}
function previewEditorRoute(){const target=previewTarget();if(target)return target.topicId?`edit?id=${target.topicId}`:'new';const id=routeInfo().query.get('id');return id==='new'?'new':id?`edit?id=${Number(id)}`:editorRoute()}
function resultSnapshot(r){if(!r.topicId&&!r.id||r.status==='skipped')return r;const topic=getTopic(r.topicId||r.id);if(!topic)return{...r,status:'withdrawn',message:'专题已移入回收站，原执行记录保留。'};const d=candidate(topic);let status=topic.status;if(status==='published'&&!publicTopic(topic)||['draft','pending'].includes(status)&&Object.keys(validateDraft(d,true)).length)status='waiting';return{...r,title:d.title,count:validIds(d.ids).length,status,message:status===r.status?r.message:'已同步当前专题状态，原执行记录保留。'}}
function topicStatus(t){if(t.publicDraft&&t.status==='pending')return`${statusTag('published')}<span class="tiny muted">更新待审核</span>`;return`${statusTag(t.status)}${t.publicDraft&&JSON.stringify(candidate(t))!==JSON.stringify(t.publicDraft)?'<span class="tiny muted">有未发布修改</span>':''}`}
function go(route,params=''){const target=`/${route}${params?'?'+params:''}`;if(location.hash==='#'+target){render();return}location.hash=target}
function notify(message){clearTimeout(window.toastTimer);const el=document.getElementById('toast');el.textContent=message;el.hidden=false;window.toastTimer=setTimeout(()=>el.hidden=true,4400)}
function safeReturn(value,fallback='topics'){const route=(value||'').split('?')[0];return['new','edit','task-new','settings','batch','library-edit','workspace'].includes(route)?value:fallback}
function formError(key){return state.errors[key]?`<p class="error" id="${key}-error" role="alert">${esc(state.errors[key])}</p>`:''}
function emptyResource(title,text,front=false){const route=routeInfo().route;const back=front?'channel':route.startsWith('task-')?'tasks':route==='library-edit'?'libraries':route==='batch-results'?'batch':'topics';const label={channel:'浏览可用专题',tasks:'返回任务列表',libraries:'返回标题库列表',batch:'返回批量新建',topics:'返回专题列表'}[back];const body=`<div class="empty-state"><div class="empty-icon">${icon('file')}</div><h1 style="font-size:24px">${title}</h1><p>${text}</p>${link(back,label,'btn primary')}</div>`;return front?frontShell(body,routeInfo().route):adminShell(body)}

const link=(route,label,cls='btn',params='')=>`<a class="${cls}" ${label.startsWith('<svg')&&label.endsWith('</svg>')?'aria-label="阅读文章"':''} href="${esc('#/'+route+(params?'?'+params:''))}">${label}</a>`;
const btn=(action,label,cls='btn',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;

const badge=(text,type='')=>`<span class="tag ${type}">${esc(text)}</span>`;

const notice=(title,text,type='info',actions='')=>`<div class="notice ${type==='info'?'':type}">${icon(type==='warning'||type==='danger'?'alert':type==='success'?'check':'info')}<div><strong>${title}</strong>${text?`<p>${text}</p>`:''}${actions?`<div class="actions">${actions}</div>`:''}</div></div>`;

const field=(label,control,help='',optional=false)=>`<div class="field"><label ${control.match(/id="([^"]+)"/)?.[1]?'for="'+control.match(/id="([^"]+)"/)[1]+'"':''}>${label}${optional?'<span class="optional">可选</span>':''}</label>${control.replace(/aria-label="[^"]*"/g,'aria-label="'+esc(label)+'"')}${help?`<p class="help">${help}</p>`:''}</div>`;

const input=(name,value,placeholder='',type='text')=>`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" data-field="${name}" aria-label="${name==='title'?'专题标题':name}">`;

const textarea=(name,value,placeholder='',rows=3)=>`<textarea id="${name}" name="${name}" data-field="${name}" rows="${rows}" placeholder="${esc(placeholder)}" aria-label="${name}">${esc(value)}</textarea>`;

const select=(name,choices,value)=>`<select id="${name}" data-field="${name}" aria-label="${name}">${choices.map(c=>{const [v,t]=Array.isArray(c)?c:[c,c];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}</select>`;

const toggle=(name,checked)=>`<input class="toggle" type="checkbox" data-field="${name}" aria-label="${name}" ${checked?'checked':''}>`;

const panel=(title,body,action='',description='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${action}</div><div class="panel-body">${body}</div></section>`;

const heading=(title,sub,actions='')=>`<div class="heading-row"><div><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div><div class="actions">${actions}</div></div>`;

const layoutName=(value)=>({default:'标准聚合',guide:'阅读指南',roundup:'资讯盘点'}[value]||'标准聚合');

function prototypeBar(route){const i=Math.max(0,pages.findIndex(p=>p[0]===route));return `<div class="prototype-bar"><div class="proto-label"><strong>GEOFlow · 交互原型</strong><span class="proto-copy">　本窗口模拟数据，刷新后重置</span></div><div class="proto-tools">${link('overview','页面目录','')}${btn('previous','上一个','previous') }<select aria-label="跳转原型页面" data-field="page-route">${pages.map((p,k)=>`<option value="${p[0]}" ${route===p[0]?'selected':''}>${String(k+1).padStart(2,'0')} ${p[1]}</option>`).join('')}</select>${btn('next','下一个')}${btn('reset','重置体验','reset')}</div></div>`}

function adminShell(content,section='topics',title='内容管理'){return `${prototypeBar(routeInfo().route)}<aside class="sidebar" id="sidebar"><a class="brand" href="#/overview">GEOFlow</a><a class="nav-item ${section==='workspace'?'active':''}" href="#/workspace">${icon('spark')}AI 工作台</a><div class="nav-section">数据</div><a class="nav-item" href="#" data-action="existing-module" data-name="数据中心">${icon('grid')}数据中心</a><div class="nav-section">内容</div><a class="nav-item ${section==='tasks'?'active':''}" href="#/tasks">${icon('tasks')}任务管理</a><a class="nav-item ${section==='topics'?'active':''}" href="#/topics">${icon('file')}内容管理</a><a class="nav-item ${section==='library'?'active':''}" href="#/libraries">${icon('library')}内容资产</a><div class="nav-section">分发</div><a class="nav-item" href="#" data-action="existing-module" data-name="分发管理">${icon('globe')}分发管理</a><a class="nav-item" href="#" data-action="existing-module" data-name="内链投放">${icon('link')}内链投放</a><div class="nav-section">系统</div><a class="nav-item ${section==='ai'?'active':''}" href="#/ai-settings">${icon('spark')}AI 配置器</a><a class="nav-item ${section==='settings'?'active':''}" href="#/settings">${icon('settings')}网站设置</a><div class="nav-section">最近访问</div><a class="nav-item" href="#/edit">${icon('layers')}GEO 专题页设计</a><div class="sidebar-foot"><span class="avatar">编</span>内容编辑　<span class="tiny">演示账号</span></div></aside><div class="admin-area"><header class="topbar"><div class="topbar-title">${btn('mobile-menu',icon('menu'),'icon-btn mobile-toggle','aria-label="打开菜单"')}${icon(section==='tasks'?'tasks':section==='settings'?'settings':section==='library'?'library':section==='ai'||section==='workspace'?'spark':'file')}${title}</div><div class="topbar-right"><span class="desktop">${icon('bell')}</span><span class="desktop">简体中文</span><span class="avatar">编</span></div></header><main class="page" id="main-content">${content}</main></div>`}

function subnav(){const active=['review','trash'].includes(routeInfo().route)?routeInfo().route:'topics';return `<nav class="subnav" aria-label="内容管理"><a href="#/topics" data-action="article-tab"><span class="dot" style="color:#2563eb"></span>文章列表</a><a class="${active==='topics'?'active':''}" href="#/topics"><span class="dot" style="color:#0ea77b"></span>专题列表</a><a href="#" data-action="existing-module" data-name="分类管理"><span class="dot" style="color:#8b5cf6"></span>分类管理</a><a class="${active==='review'?'active':''}" href="#/review"><span class="dot" style="color:#f59e0b"></span>审核中心</a><a class="${active==='trash'?'active':''}" href="#/trash"><span class="dot" style="color:#6b7280"></span>回收站</a></nav>`}

function overview(){const groups=['内容管理','自动化','模板与设置','状态与维护','网站前台'];return `${prototypeBar('overview')}<main class="gallery" id="main-content"><div class="gallery-top"><div class="eyebrow">GEOFlow / Topic channel / v2.5</div><h1>专题功能，逐页体验。</h1><p>从已有文章整理一个专题，再把这件事交给标题库与 AI 任务。这里包含 ${pages.length-1} 个相关页面，表单、生成、发布和重试均可点击。页面顶部可随时切换，刷新后恢复初始演示数据。</p><div class="gallery-paths">${link('topics',`${icon('file')}从单个专题开始`,'')}${link('batch',`${icon('layers')}体验批量生成`,'')}${link('task-new',`${icon('tasks')}体验自动任务`,'')}${link('home',`${icon('globe')}直接看网站前台`,'')}</div></div>${groups.map(g=>`<section class="gallery-group"><h2>${g}</h2><div class="gallery-grid">${pages.map((p,i)=>p[3]===g?`<a class="gallery-item" href="#/${p[0]}"><span class="gallery-number">${String(i+1).padStart(2,'0')}</span><div><strong>${p[1]}</strong><p>${p[2]}</p></div>${icon('arrow')}</a>`:'').join('')}</div></section>`).join('')}<div class="gallery-footer">原型范围：专题管理、文章组合、标题库与任务、模板和设置、异常引导、前台首页与阅读。AI 和发布均为流程模拟，未连接实际站点。</div></main>`}

function templateCards(chosen,action='choose-template'){
  return `<div class="template-grid">${[['default','标准聚合','适合主题文章合集，摘要、选文与来源清晰展开。'],['guide','阅读指南','按步骤或阶段安排阅读，突出先读什么、再读什么。'],['roundup','资讯盘点','按时间整理文章，显示本次整理日期与观察范围。']].map(([id,name,desc])=>`<div class="template-choice ${chosen===id?'selected':''}"><a href="#/template-preview?layout=${id}" class="template-thumb" aria-label="预览${name}"><div class="mini-sheet"><div class="mini-rule"></div><div class="mini-lines"></div><div class="mini-lines short"></div>${id==='guide'?'<div class="mini-section">01　理解基础</div><div class="mini-section">02　实践方法</div><div class="mini-section">03　观察效果</div>':id==='roundup'?'<div class="mini-section">2026.09　最近整理</div><div class="mini-lines"></div><div class="mini-rule"></div><div class="mini-lines short"></div>':'<div class="mini-score">8.5<small> / 10</small></div><div class="mini-section">摘要　文章　来源</div><div class="mini-lines"></div>'}</div></a><div class="template-meta"><h3>${name}${chosen===id?badge('已选择','blue'):''}</h3><p>${desc}</p><div class="actions">${btn(action,chosen===id?'已选择':'使用模板',chosen===id?'btn small':'btn primary small',`data-layout="${id}"`)}${link('template-preview','预览','text-btn',`layout=${id}`)}</div></div></div>`).join('')}</div>`;
}

function templatesPage(){return adminShell(`${heading('专题模板管理','一套模板覆盖前台首页、专题列表和专题详情页。',link('home',`${icon('eye')}查看网站前台`,'btn primary'))}${notice('专题组件已接入当前网站模板','首页专题模块与列表共用字段，详情模板可按专题选择。','success')}<section class="panel"><div class="panel-head"><h2>专题详情模板</h2>${badge('3 个可用模板','blue')}</div><div class="panel-body">${templateCards(state.settings.layout)}</div></section><section class="panel"><div class="panel-head"><h2>网站模板中的专题位置</h2></div><div class="panel-body"><div class="article-item"><span class="article-index">01</span><div class="article-info"><h3>网站首页</h3><p>专题模块显示标题、导读、文章数、标签与实际更新时间。</p></div>${link('home','预览首页','btn small')}</div><div class="article-item"><span class="article-index">02</span><div class="article-info"><h3>专题列表页</h3><p>支持搜索与主题筛选，进入专题详情继续阅读。</p></div>${link('channel','预览列表','btn small')}</div><div class="article-item"><span class="article-index">03</span><div class="article-info"><h3>文章详情页</h3><p>显示文章所属专题，把单篇阅读接回完整主题。</p></div>${link('article','预览回链','btn small')}</div></div></section>${panel('模板调用规范',`<div class="summary-fact"><strong>共用字段与组件</strong><p class="help">专题标题、简介、文章、分组、摘要、标签、时间、评分与来源，在各模板间保持一致。</p></div><div class="summary-fact"><strong>兼容当前网站模板</strong><p class="help">旧模板通过默认专题组件获得列表与详情能力，可以逐步定制外观。</p></div><div class="summary-fact"><strong>缺失内容自动简化</strong><p class="help">没有评分、FAQ 或封面时，隐藏对应模块并收拢留白。</p></div>`)}`,'settings','网站设置')}

function aiSettingsPage(){return adminShell(`${link(safeReturn(routeInfo().query.get('return'),'settings'),`${icon('back')}返回刚才的页面`,'back-link')}${heading('AI 配置器','连接一个文本模型，即可用于文章与专题生成。')}${notice(state.aiReady?'演示模型已准备好':'连接模型后，继续刚才的专题',state.aiReady?'本原型模拟模型响应，可体验生成、超时重试与切换。':'标题、选文和草稿已保留。连接完成后可以直接回到编辑。',state.aiReady?'success':'info')}<div class="edit-layout"><div>${panel('模型连接',`${field('服务商',select('ai-provider',['OpenAI 兼容服务','其他兼容服务'],'OpenAI 兼容服务'))}${field('连接名称',input('ai-name','专题生成模型','便于识别的名称'))}${field('接口地址',input('ai-url','https://example.com/v1','兼容服务地址'))}${field('API Key',input('ai-key','','原型无需填写真实密钥','password'))}${field('模型名称',input('ai-model','演示文本模型','服务商提供的模型名称'))}<div class="actions">${btn('test-ai',`${icon('link')}模拟测试连接`)}${btn('save-ai','保存并继续','btn primary')}</div><p class="help">这是演示连接，不发送网络请求，也不存储密钥。</p>`)}</div><aside><section class="side-block"><h3>继续使用</h3><p class="help">手工创建可以随时使用。AI 帮助选文、组织导读、生成摘要和补充标题。</p>${link('new','先手工创建专题','text-btn')}</section></aside></div>`,'ai','AI 配置器')}

const frontTags=(tags='GEO,AI 搜索,内容组织,结构化摘要')=>`<div>${tags.split(/[,，]/).map(t=>t.trim()).filter(Boolean).map((t,i)=>`<span class="front-tag ${i===0?'main':''}">${esc(t)}</span>`).join('')}</div>`;

function frontHeader(){return `<header class="front-header"><a class="front-brand" href="#/home">GEOFlow<span>内容实践笔记</span></a><nav class="front-nav" aria-label="网站导航"><a href="#/home">首页</a><a href="#/article">文章</a>${state.settings.nav?`<a href="#/channel">${esc(state.settings.channel)}</a>`:''}<a href="#/channel?tag=GEO">GEO</a></nav></header>`}

const frontFooter=()=>`<footer class="front-footer"><span>GEOFlow · 内容实践笔记</span><span>原型演示内容　${link('topics','进入后台','')}</span></footer>`;

function frontShell(content,route){return `${prototypeBar(route)}<div class="front">${frontHeader()}<main class="front-main" id="main-content">${content}</main>${frontFooter()}</div>`}

function topicFeature(t){return `<a class="topic-feature" href="#/${t.layout==='guide'?'guide':t.layout==='roundup'?'roundup':'detail'}?id=${t.id}"><span class="eyebrow">${layoutName(t.layout)}</span><h3>${esc(t.title)}</h3><p>${esc(t.intro)}</p><div class="topic-feature-meta"><span>${t.ids.length} 篇文章</span><span>2026.${t.date.split(' ')[0]} 更新 ${icon('arrow')}</span></div></a>`}

function homePage(){const published=featuredTopics();return frontShell(`<section class="front-home-head"><div class="front-kicker">GEO · CONTENT · AI SEARCH</div><h1>把内容串起来，<br>让理解多走一步。</h1><p>记录内容组织、AI 搜索和专题页面的实际做法。<br>从一篇文章开始，也可以沿着主题读下去。</p>${link('channel',`浏览专题 ${icon('arrow')}`,'btn navy')}</section>${state.settings.home?`<section class="front-section"><div class="front-section-head"><div><div class="front-kicker">TOPICS</div><h2>从${esc(state.settings.channel)}开始阅读</h2></div>${link('channel',`全部${esc(state.settings.channel)} ${icon('arrow')}`,'text-btn')}</div><div class="topic-feature-list">${published.slice(0,Number(state.settings.homeCount)).map(topicFeature).join('')}</div></section>`:''}<section class="front-section"><div class="front-section-head"><div><div class="front-kicker">LATEST NOTES</div><h2>最近的文章</h2></div>${link('article','继续阅读','text-btn')}</div><div class="home-articles"><a class="home-feature" href="#/article?id=209"><span class="eyebrow">自动化　2026.09.29</span><h3>自动维护专题时，<br>如何保留人工修改</h3><p>以人工修改为基础，让 AI 为变化的来源提供可理解的更新建议。</p><span class="text-btn">阅读全文 ${icon('arrow')}</span></a><div class="home-list">${[208,202,201].map(id=>{const a=articles.find(x=>x.id===id);return `<a href="#/article?id=${id}"><span class="eyebrow">${esc(a.category)}　${a.date}</span><h3>${esc(a.title)}</h3><p>${esc(a.excerpt)}</p></a>`}).join('')}</div></div></section>`,'home')}

function channelPage(){const query=routeInfo().query;const search=query.get('q')||'';const tag=query.get('tag')||'全部';const topics=featuredTopics().filter(t=>(!search||`${t.title} ${t.intro}`.toLowerCase().includes(search.toLowerCase()))&&(tag==='全部'||tag==='GEO'||(tag==='入门阅读'?t.layout==='guide':tag==='内容盘点'?t.layout==='roundup':true)));return frontShell(`<div class="breadcrumbs">${link('home','首页','')}<span>/</span>${esc(state.settings.channel)}</div><section class="channel-title"><div class="front-kicker">TOPIC COLLECTION</div><h1>${esc(state.settings.channel)}</h1><p>把已有文章按主题整理，在摘要、来源与阅读路径中找到下一步。</p></section><div class="filters" style="margin-bottom:26px">${input('front-search',search,'搜索你想了解的主题…')}${btn('front-search',`${icon('search')}搜索`,'btn navy')}</div><nav class="front-chipnav" aria-label="专题主题">${['全部','GEO','入门阅读','内容盘点'].map(t=>link('channel',t,tag===t?'active':'',t==='全部'?'':`tag=${encodeURIComponent(t)}`)).join('')}</nav><div>${topics.map((t,i)=>`<article class="channel-item"><span class="channel-index">${String(i+1).padStart(2,'0')}</span><div><span class="eyebrow">${layoutName(t.layout)} · ${t.ids.length} 篇文章</span><h2><a href="#/${t.layout==='guide'?'guide':t.layout==='roundup'?'roundup':'detail'}?id=${t.id}">${esc(t.title)}</a></h2><p>${esc(t.intro)}</p>${frontTags(t.layout==='guide'?'AI 搜索,入门阅读':t.layout==='roundup'?'GEO,内容盘点,实际整理月份':'GEO,内容组织,结构化摘要')}</div><div class="channel-side"><span>2026.${t.date.split(' ')[0]} 更新</span>${link(t.layout==='guide'?'guide':t.layout==='roundup'?'roundup':'detail',`进入专题 ${icon('arrow')}`,'text-btn',`id=${t.id}`)}</div></article>`).join('')||`<div class="empty-state"><h3>暂时没有找到这个主题</h3><p>换个关键词，或浏览现有专题。</p>${link('channel','查看全部专题','btn navy')}</div>`}</div>`,'channel')}

function scoreCard(){return `<section class="score-card"><div class="score-label">AI ASSISTED SCORE</div><div class="score-big">8.5 <small>/ 10</small></div><div class="score-stars" aria-label="展示分数 4.25 / 5 星"><span aria-hidden="true">★★★★★</span><span class="star-fill" aria-hidden="true">★★★★★</span></div>${[['主题完整度','8.4'],['阅读易用性','8.5'],['来源可追溯性','8.4'],['信息时效表达','8.6']].map(([name,score])=>`<div class="score-row"><span>${name}</span><div class="score-line"><span style="width:${Number(score)*10}%"></span></div><span>${score}</span></div>`).join('')}<p class="score-note">AI 辅助评分 · 仅为原型演示<br>8.5 / 10 = 4.25 / 5 星，星形按同一分数比例填充。</p></section>`}


state.newDraft=newDraft();

function topicsPage(empty=false){
  const filtered=state.topics.filter(t=>(state.filter==='all'||t.status===state.filter)&&candidate(t).title.includes(state.search)&&(state.taskFilter==='all'||String(sourceTask(t)?.id)===state.taskFilter));
  const selected=filtered.filter(t=>state.selected.has(t.id)).length;
  const body=empty?panel('专题列表',`<div class="empty-state"><div class="empty-icon">${icon('layers')}</div><h2>把已有文章，整理成一个专题。</h2><p>填一个标题，让 AI 帮你选择、编排和生成导读；也可以手工选文。</p><div class="actions">${link('new','新建专题','btn primary')}${link('batch','批量新建')}${link('task-new','创建专题任务')}</div></div>`):`
  <div class="stats">${[['全部专题',state.topics.length],['公开专题',featuredTopics().length],['草稿',state.topics.filter(t=>t.status==='draft').length],['待处理',state.topics.filter(t=>t.status==='waiting').length]].map(([name,value])=>`<div class="stat"><span class="stat-label">${name}</span><strong class="stat-number">${value}</strong></div>`).join('')}</div>
  ${panel('筛选与搜索',`<div class="filters">${field('发布状态',select('topic-filter',[['all','全部状态'],['published','已发布'],['draft','草稿'],['pending','待审核'],['waiting','待处理']],state.filter))}${field('关联任务',select('task-filter',[['all','所有任务'],...state.tasks.filter(t=>t.kind==='topic').map(t=>[String(t.id),t.name])],state.taskFilter))}${field('标题搜索',input('search',state.search,'搜索专题标题…'))}${btn('search',`${icon('search')}搜索`,'btn primary')}${btn('clear-search','清空')}</div>`)}
  <div class="tabs">${[['all','全部'],['published','已发布'],['draft','草稿'],['pending','待审核'],['waiting','待处理']].map(([v,label])=>btn('filter',label,`tab ${state.filter===v?'active':''}`,`data-value="${v}"`)).join('')}${link('trash','专题回收站','text-btn muted')}</div>
  <section class="panel"><div class="panel-head"><h2>专题列表 <span class="muted small">（${filtered.length} 个）</span></h2><div class="actions"><span class="tiny muted" id="selected-count">已选 ${selected} 个</span>${btn('bulk-publish','发布所选','btn small',selected?'':'disabled')}${link('batch-results','批次结果','btn small')}</div></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" aria-label="选择当前筛选内的全部专题" data-field="all-topics" ${selected&&selected===filtered.length?'checked':''}></th><th>专题信息</th><th>文章</th><th>创建来源</th><th>状态</th><th>公开更新</th><th>操作</th></tr></thead><tbody>${filtered.map(t=>{const d=candidate(t);return`<tr><td><input type="checkbox" data-field="topic-check" data-id="${t.id}" aria-label="选择 ${esc(d.title)}" ${state.selected.has(t.id)?'checked':''}></td><td><a class="row-title" href="#/edit?id=${t.id}">${esc(temporalTitle(d))}</a><p class="row-copy">${esc(d.intro)}</p>${d.scopeNote?`<p class="row-copy">范围：${esc(d.scopeNote)}</p>`:''}${badge(layoutName(d.layout))}</td><td>${validIds(d.ids).length} 篇</td><td>${sourceTask(t)?link('task-detail',esc(sourceTask(t).name),'small',`id=${sourceTask(t).id}`):esc(t.source||'人工整理')}</td><td>${topicStatus(t)}</td><td class="tiny muted">${t.publicDraft?.updatedAt||'尚未发布'}</td><td><div class="row-actions">${link('edit','编辑','',`id=${t.id}`)}${link(d.layout==='guide'?'guide':d.layout==='roundup'?'roundup':'detail','预览','',`id=${t.id}&preview=1`)}${t.publicDraft?link(t.publicDraft.layout==='guide'?'guide':t.publicDraft.layout==='roundup'?'roundup':'detail','查看','',`id=${t.id}`):''}${btn('trash-topic',icon('trash'),'text-btn muted',`data-id="${t.id}" aria-label="移入回收站"`)}</div></td></tr>`}).join('')||'<tr><td colspan="7" class="muted">没有匹配的专题，清空筛选后继续查看。</td></tr>'}</tbody></table></div><div class="pagination"><span>显示 ${filtered.length} 个专题 · 可在表格内左右滚动</span><span>1 / 1</span></div></section>${state.bulkResult?notice('批量操作结果',esc(state.bulkResult),'info'):''}`;
  return adminShell(`${subnav()}${heading('专题列表','围绕一个主题，重新组织本站已有文章。',link('new',`${icon('plus')}${state.newDraft.title?'继续新建专题':'新建专题'}`,'btn primary')+link('batch','批量新建')+link('task-new','创建专题任务'))}<div style="display:flex;justify-content:flex-end;margin:-10px 0 15px">${link('settings',`${icon('settings')}专题设置`,'text-btn')}</div>${body}`);
}
function scenarioNotice(){const d=draft();const x=state.scenarioTarget===targetKey()?state.scenario:'normal';
  if(!state.aiReady)return notice('还没有可用的 AI 模型','你可以先手工整理。配置 AI 后，刚才的标题、选文和文字都会保留。','warning',link('ai-settings','配置 AI','btn small',`return=${encodeURIComponent(editorRoute())}`)+btn('manual-mode','手工选文','btn small'));
  if(x==='timeout')return notice('这次 AI 请求没有完成','输入已保留。重新生成只补充空白内容，人工文字可以先对照建议。','warning',btn('retry-generate','重新生成','btn primary small')+link('ai-settings','选择其他模型','btn small',`return=${encodeURIComponent(editorRoute())}`));
  if(x==='conflict')return notice('已保留你的修改','AI 建议已经准备好，可以查看后决定采用哪些文字。','info',btn('show-suggestion','查看建议','btn small'));
  if(x==='withdrawn')return notice('一篇来源文章已撤回','公开页与摘要已隐藏对应内容。可以选择有效替代，其他内容继续保留。','warning',btn('replace-source','AI 重新整理','btn primary small')+link('select','手工替换','btn small'));
  if(d?.articleNotice)return notice('相关文章需要补充',d.articleNotice,'warning',link('select','选择文章','btn primary small')+btn('broaden-scope','查看全部公开文章','btn small'));
  return '';
}
const editorRoute=()=>state.editorKind==='new'?'new':`edit?id=${state.editId}`;
function articleCards(d){const ids=validIds(d.ids);return ids.length?ids.map((id,i)=>{const a=articles.find(a=>a.id===id);return`<div class="article-item"><span class="article-index">${String(i+1).padStart(2,'0')}</span><div class="article-info"><h3>${esc(a.title)}</h3><p>${esc(a.excerpt)}</p>${link('article','查看原文','text-btn',`id=${a.id}`)}<div class="article-group-control"><label for="group-${id}">阅读分组</label><select id="group-${id}" data-field="article-group" data-id="${id}">${['不分组',...new Set([...groupChoices,...Object.values(d.groups||{})])].map(g=>`<option value="${esc(g)}" ${(d.groups?.[id]||'不分组')===g?'selected':''}>${esc(g)}</option>`).join('')}</select></div></div><div class="article-buttons">${btn('article-up',icon('up'),'icon-btn',`data-id="${id}" aria-label="上移文章" ${i===0?'disabled':''}`)}${btn('article-down',icon('down'),'icon-btn',`data-id="${id}" aria-label="下移文章" ${i===ids.length-1?'disabled':''}`)}${btn('remove-article',icon('x'),'icon-btn',`data-id="${id}" aria-label="移除文章"`)}</div></div>`}).join(''):`<div class="empty-state" style="padding:25px"><div class="empty-icon">${icon('layers')}</div><h3>为这个主题选出相关文章</h3><p>填写标题后让 AI 整理，也可以直接手工选择。</p>${link('select','选择文章','btn primary')}</div>`}
function suggestionBlock(){const s=state.suggestions[targetKey()];return s?`<section class="panel" id="ai-suggestion"><div class="panel-head"><h2>AI 摘要建议</h2>${badge('等待你选择','blue')}</div><div class="panel-body"><div class="two-fields"><div class="suggestion-text"><span class="eyebrow">当前文字</span><p>${esc(draft().one||'尚未填写')}</p></div><div class="suggestion-text"><span class="eyebrow">AI 建议</span><p>${esc(s.one)}</p></div></div><div class="actions">${btn('adopt-suggestion','采用这条建议','btn primary')}${btn('dismiss-suggestion','保留当前文字')}</div><p class="help">采用后仍可修改。选文、标题和其他字段继续保留。</p></div></section>`:''}
function editorPage(isNew=false){
  state.editorKind=isNew?'new':'edit';if(!isNew&&routeInfo().query.has('id'))state.editId=Number(routeInfo().query.get('id'));
  if(!isNew&&!getTopic(state.editId))return emptyResource('这个专题暂时无法编辑','它可能已移入回收站，也可能属于另一个原型窗口。请返回专题列表查看。');
  const d=draft();d.groups??={};const t=isNew?null:getTopic(state.editId);const key=targetKey();const errors=state.errors[key]||{};const running=state.generations[key];
  const temporalHelp=['annual','as_of'].includes(d.freshness)&&temporalTitle(d)===d.title.trim()?'<p class="help">补充日期与依据后显示时效标题；当前预览保留常青标题。</p>':'';
  const articleBody=running?`<div class="processing" id="generation-progress"><span class="spinner"></span><h3>${running.phase||'正在寻找相关文章'}</h3><p>可以继续编辑文字，生成结果会保留在这个专题中。</p>${btn('cancel-generation','停止本次生成','btn small')}</div>`:articleCards(d);
  return adminShell(`${link('topics',`${icon('back')}返回专题列表`,'back-link')}${heading(isNew?'新建专题':'编辑专题',isNew?'填一个标题，让 AI 帮你整理；也可以手工创建。':'调整选文与表达，预览后发布更新。',(t?link('history','历史版本','btn small',`id=${t.id}`):'')+btn('save',`${icon('check')}保存草稿`,'btn small'))}${scenarioNotice()}${Object.keys(errors).length?notice('还有内容需要补充','按标记补充即可。当前输入已保留，可以随时保存草稿。','warning'):''}<div class="edit-layout"><div>
  ${panel('标题与简介',`${field('专题标题',input('title',d.title,'例如：AI 搜索入门与常见问题'))}<p class="error" id="title-error" ${errors.title?'':'hidden'}>${esc(errors.title||'先填写一个专题标题。')}</p>${field('简介 / 导读',textarea('intro',d.intro,'说明覆盖什么、适合谁，以及从哪里开始阅读。'))}${errors.intro?'<p class="error" id="intro-error">补充一段准确导读，再发布专题。</p>':''}<div class="actions">${btn('generate',`${icon('spark')}${d.generated?'AI 补充与优化':'AI 生成专题'}`,'btn primary',running?'disabled':'')}<span class="help">${d.generated?'保留人工文字，建议单独对照':'选文、分组、导读、摘要与标签'}</span></div><p class="tiny muted">原型文章围绕 GEO 与 AI 搜索，其他主题可以先手工选文体验。</p>`)}
  ${panel(`文章与编排 <span class="muted small">${validIds(d.ids).length} 篇</span>`,`${errors.articles?`<div class="notice warning" id="articles-error"><div><strong>再补充 ${Math.max(0,2-validIds(d.ids).length)} 篇公开文章，就能组成专题。</strong><p>保存草稿随时可用。发布需要两篇不同文章和准确导读。</p>${link('select','选择文章','btn small primary')}</div></div>`:''}${articleBody}${validIds(d.ids).length?`<details class="advanced" style="margin-top:15px"><summary>添加自定义阅读分组</summary><div class="actions">${input('new-group','','例如：从准备到实践')}${btn('add-group','添加分组')}</div></details>`:''}`,link('select',`${icon('plus')}选择文章`,'btn small'))}
  ${panel('结构化摘要',`${field('一句话结论',textarea('one',d.one,'用一两句话说明专题的核心价值。',2))}${field('适用范围与限制',textarea('scopeNote',d.scopeNote||'','例如：面向初次使用的读者，覆盖首次设置与基础操作。',2),'按需要填写；同名专题的范围不同，可以分别保存。',true)}${d.generated?facts.filter(f=>validIds(d.ids).includes(f.source)).map(f=>`<div class="summary-fact"><strong>${f.title}</strong><p>${f.text}</p>${link('article',`依据：${esc(articles.find(a=>a.id===f.source).title)}`,'source-ref',`id=${f.source}`)}</div>`).join(''):'<p class="help">关键事实可在生成后查看，每条都保留来源。</p>'}${field('内容标签',input('tags',d.tags,'用逗号分隔'),'标签与正文语义保持一致。',true)}`,btn('regenerate-summary',`${icon('spark')}获取摘要建议`,'btn small'))}${suggestionBlock()}
  <section class="panel"><details class="advanced"><summary>更多设置：时效标题、评分与人工修改</summary>${field('时效标题',select('freshness',[['evergreen','常青标题'],['composed_at','加入实际整理月份'],['annual','有依据的版本年份'],['as_of','有依据的事实截至日期']],d.freshness),'切换模板只改变布局，标题时间由这里决定。')}${d.freshness==='annual'?field('版本年份',input('coverage-year',d['coverage-year'],'例如 2026')):d.freshness==='as_of'?field('事实截至日期',input('coverage-date',d['coverage-date'],'','date')):''}${['annual','as_of'].includes(d.freshness)?field('日期依据',textarea('coverage-note',d['coverage-note'],'说明该版本年份或截至日期对应的事实范围。',2)):''}${temporalHelp}<div class="inline-info"><span class="tiny muted">标题预览</span><strong id="temporal-title-preview">${esc(temporalTitle(d))}</strong></div><div class="switch-line"><div><strong>展示评分卡</strong><p>显示演示评分和依据说明。普通专题无需填写。</p></div>${toggle('score',d.score)}</div><div class="switch-line"><div><strong>保留人工修改</strong><p>AI 补充空白内容，已写好的摘要先展示建议。</p></div>${toggle('protect',d.protect)}</div></details></section>
  </div><aside class="sticky publish-side"><section class="side-block"><h3>发布</h3><div class="side-line"><span>当前状态</span>${t?topicStatus(t):badge('未保存的新专题')}</div><div class="side-line"><span>发布到</span><strong>GEOFlow 演示站</strong></div><div class="side-line"><span>有效文章</span><strong>${validIds(d.ids).length} 篇</strong></div><div class="divider"></div>${field('专题模板',select('layout',[['default','标准聚合'],['guide','阅读指南'],['roundup','资讯盘点']],d.layout))}${link('template-preview','切换并预览模板','text-btn','draft=1&layout='+d.layout+'&'+draftIdentityQuery())}<div class="divider"></div>${btn('preview',`${icon('eye')}前台预览`,'btn wide')}<div style="margin-top:10px">${btn('publish',state.settings.review?'提交审核':t?.publicDraft?'发布更新':'发布专题','btn primary wide',running?'disabled':'')}</div><p class="help">${running?'本次生成完成后可发布。':t?.publicDraft?'保存草稿会保留旧公开内容，发布后再更新。':state.settings.review?'沿用网站的人工审核设置。':'普通专题可以直接发布。'}</p></section><section class="side-block"><h3>当前修改</h3><p class="help">表单在本次体验中保留。保存为草稿后，可从列表继续编辑。</p>${link('settings','查看专题设置','text-btn','return='+encodeURIComponent(editorRoute()))}</section></aside></div>`);
}
function selectionPage(){const d=draft();if(!d)return emptyResource('先打开一个专题','从列表选择专题后，再选择要加入的文章。');const usable=articles.filter(a=>isPublicArticle(a)&&!state.unavailable.has(a.id));const filtered=usable.filter(a=>(state.picker.category==='全部分类'||a.category===state.picker.category)&&a.title.includes(state.picker.search));return adminShell(`${link(editorRoute(),`${icon('back')}返回专题编辑`,'back-link')}${heading('选择与编排文章',`已选择 ${validIds(d.ids).length} 篇。移除关联只影响专题，原文章仍保留。`,btn('finish-select','完成选择','btn primary'))}${panel('本站公开文章',`<div class="filters">${field('分类',select('picker-category',['全部分类',...new Set(usable.map(a=>a.category))],state.picker.category))}${field('搜索标题',input('picker-search',state.picker.search,'搜索文章标题…'))}${btn('picker-search','搜索')}${btn('clear-picker','清空')}</div><div class="selection-tools"><span class="help">找到 ${filtered.length} 篇文章</span><div class="actions">${btn('pick-visible','选择当前结果','btn small')}${btn('unpick-visible','取消当前结果','btn small')}</div></div><div id="article-options">${filtered.map(a=>`<label class="article-item"><input type="checkbox" data-field="pick-article" data-id="${a.id}" ${d.ids.includes(a.id)?'checked':''} aria-label="选择 ${esc(a.title)}"><div class="article-info"><h3>${esc(a.title)}</h3><p>${esc(a.excerpt)}</p>${badge(a.category)}<span class="tiny muted">发布于 ${a.date}</span></div><span class="picked-status tag ${d.ids.includes(a.id)?'blue':'green'}">${d.ids.includes(a.id)?'已选':'可公开'}</span></label>`).join('')||`<div class="empty-state"><h3>没有匹配的公开文章</h3><p>清空搜索或换一个分类，继续选择已有内容。</p>${btn('clear-picker','查看全部文章','btn primary')}</div>`}</div>`)}<div class="form-footer selection-footer"><strong id="picked-count">已选 ${validIds(d.ids).length} 篇</strong>${btn('finish-select','完成选择并返回','btn primary')}</div>`)}

function batchPage(){const f=state.batchForm;let rows=[];try{rows=batchRows(f.raw,f.scope,f.scopeNote)}catch{}const total=rows.length;const distinctCount=new Set(rows.map(topicKey)).size;return adminShell(`${link('topics',`${icon('back')}返回专题列表`,'back-link')}${heading('批量新建专题','每行一个标题，每个主题单独生成。重复项会说明对应的原专题或本批记录。')}<div class="edit-layout"><div>${panel('准备专题标题',`${field('标题清单',textarea('batchInput',f.raw,'每行一个专题标题',8))}<div class="actions">${btn('import-batch',`${icon('upload')}导入 TXT / CSV`)}${link('library-edit','从标题库选择','text-btn','use=batch')}${btn('download-example','下载标题示例','text-btn')}<input type="file" id="batch-file" accept=".txt,.csv" hidden></div><p class="help" id="batch-title-count">${total} 行标题，${distinctCount} 个不同主题与范围。CSV 可含“标题”和可选的“适用范围与限制”列；每行范围会保留。</p>${formError('batch-import')}`,badge('标题输入','blue'))}${panel('文章与生成规则',`${field('文章范围',select('batch-scope',[['all','全部本站公开文章'],['geo','内容设计相关分类'],['recent','近 7 天公开文章']],f.scope))}${field('适用范围与限制',textarea('batch-scope-note',f.scopeNote||'','可为本批统一说明范围；CSV 每行范围优先。',2),'可留空。文章范围和每行范围随本批保存。',true)}${field('AI 生成规则',textarea('batch-rule',f.rule,'说明选文、语气或阅读分组。',4))}<p class="help">文章不足会保留草稿，其他标题继续处理。</p>`)}<details class="panel advanced demo-options"><summary>原型演示：体验不同结果</summary>${field('演示场景',select('batch-simulation',[['normal','正常生成'],['partial','模拟一次超时和一项文章不足']],f.simulation))}<p class="help">这是原型体验工具，正式系统根据真实结果显示状态。</p></details></div><aside class="sticky"><section class="side-block"><h3>本次生成</h3>${field('专题模板',select('batch-layout',[['default','标准聚合'],['guide','阅读指南'],['roundup','资讯盘点']],f.layout))}${field('生成后',select('batchAfter',[['auto_publish','自动发布'],['draft','保存为草稿'],['review','提交审核']],f.after))}<p class="help">自动发布仍沿用已保存的网站审核设置。重试使用这一批的设置。</p><div class="divider"></div><div class="side-line"><span>不同主题与范围</span><strong id="batch-distinct-count">${distinctCount} 个</strong></div>${btn('start-batch',`${icon('spark')}开始批量生成`,'btn primary wide')}<div style="margin-top:10px">${btn('batch-to-task','转为专题任务','btn wide')}</div><p class="help">按计划逐项整理，可以先带到任务设置。每行范围会保留。</p><p class="help">先选择“模拟一次超时”，可以体验逐项重试。</p></section></aside></div>`)}
function batchResultsPage(){const b=currentBatch();if(!b)return emptyResource('没有找到这个批次','返回专题列表，或重新创建一个批次。');const rows=b.rows.map(resultSnapshot);const done=rows.filter(r=>['published','draft','pending'].includes(r.status)).length;const failed=rows.filter(r=>r.status==='failed').length;const cancelled=rows.filter(r=>r.status==='cancelled').length;return adminShell(`${link('topics',`${icon('back')}返回专题列表`,'back-link')}${heading('批量生成结果',`${layoutName(b.form.layout)} · ${b.form.after==='draft'?'保存为草稿':b.form.after==='review'?'提交审核':'自动发布'} · 此批设置已保留`,btn('return-batch','返回标题与设置','btn',`data-batch="${b.id}"`)+btn('new-batch','再生成一批','btn primary'))}${b.running?notice('正在逐个处理标题',`已处理 ${b.done} / ${rows.length} 行。已完成的专题会保留。`,'info',btn('cancel-batch','停止剩余项','btn small')):notice(cancelled?'本批已停止，已完成结果保留':'本批处理已结束',`${done} 个已生成，${rows.filter(r=>r.status==='waiting').length} 个待补充文章，${failed} 个可重试${cancelled?`，${cancelled} 个本次未执行`:''}。`,failed||cancelled?'warning':'success',cancelled?btn('resume-batch',`继续处理 ${cancelled} 个剩余标题`,'btn small primary',`data-batch="${b.id}"`):'')}
  <div class="stats">${[['输入标题',rows.length],['已生成',done],['待补充文章',rows.filter(r=>r.status==='waiting').length],['重复跳过',rows.filter(r=>r.status==='skipped').length]].map(([k,v])=>`<div class="stat"><span class="stat-label">${k}</span><strong class="stat-number">${v}</strong></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>逐项结果</h2>${btn('retry-all','重试失败项','btn small',failed&&!b.running?'':'disabled')}</div><div class="table-wrap"><table><thead><tr><th>专题标题</th><th>结果</th><th>有效选文</th><th>说明</th><th>操作</th></tr></thead><tbody>${rows.map((r,i)=>`<tr id="batch-row-${i}"><td><strong class="row-title">${esc(r.title)}</strong>${r.scopeNote?`<p class="row-copy">范围：${esc(r.scopeNote)}</p>`:''}</td><td>${r.status==='failed'?badge('生成失败','red'):r.status==='skipped'?badge('重复跳过'):r.status==='queued'?badge('等待处理'):r.status==='cancelled'?badge('本次未执行','amber'):statusTag(r.status)}</td><td>${r.count||0} 篇</td><td class="muted small">${r.status==='failed'?'模拟模型超时；此标题、规则和模板均已保留':r.status==='waiting'?'相关公开文章不足，可补充后发布':r.status==='skipped'?r.message|| (r.duplicateOf!==undefined?'同批重复，使用第一次出现的处理结果':'已有同名专题，本次保留原内容'):r.status==='cancelled'?'已保留标题，可回到本批设置继续':r.status==='queued'?'尚未开始':'选文、简介和摘要已完成'}</td><td><div class="row-actions">${r.status==='failed'?btn('retry-batch',r.retrying?'正在重试':'重试','text-btn',`data-index="${i}" data-batch="${b.id}" ${r.retrying?'disabled':''}`):r.id?link('edit',r.status==='waiting'?'补充文章':r.status==='skipped'?'查看原专题':'编辑','text-btn',`id=${r.id}`):r.duplicateOf!==undefined?btn('show-batch-original','查看首次记录','text-btn',`data-index="${r.duplicateOf}"`):''}${r.id&&['published','draft','pending'].includes(r.status)?link('detail','预览','text-btn',`id=${r.id}&preview=1`):''}</div></td></tr>`).join('')}</tbody></table></div></section>`)}
function taskForm(){const q=routeInfo().query;const id=q.get('edit');const existing=id?state.tasks.find(t=>t.id===Number(id)):null;const kind=existing?.kind||(q.get('type')==='article'?'article':'topic');const key=existing?`edit:${existing.id}`:`new:${kind}`;state.activeTaskFormKey=key;const f=state.taskForms[key]??=existing?clone(existing):{...makeTaskForm(kind),libraryId:q.get('library')||'L1'};if(!existing&&q.has('library')&&state.renderedHash!==location.hash)f.libraryId=q.get('library');if(!state.libraries.some(l=>l.id===f.libraryId)){f.libraryId='';if(!f.scopedRows?.length)state.errors['task-library']='所选标题库暂不可用，请选择一个可用标题库。'}return f}
function taskSourceRows(t,lib=state.libraries.find(l=>l.id===t.libraryId)){return t.scopedRows?.length?t.scopedRows:(lib?.titles||[]).map(title=>({title,scopeNote:scopeNoteForSource(t.scope)}))}
function taskRowKey(row,t){return t.scopedRows?.length?topicKey(row):norm(row.title)}
function taskLibraryTitle(row){if(!row.scopeNote)return row.title;let code=2166136261;for(const char of topicKey(row)){code=Math.imul(code^char.charCodeAt(0),16777619)}return `${row.title}（范围：${row.scopeNote} · ${(code>>>0).toString(16).padStart(8,'0')}）`}
function scopedTaskPreview(t){return t.scopedRows?.length?panel('从批量清单带入的生成项',`<p class="help" id="task-scoped-count">已带入 ${t.scopedRows.length} 项；专题名称 ${new Set(t.scopedRows.map(row=>norm(row.title))).size} 个，标题库项 ${new Set(t.scopedRows.map(taskLibraryTitle)).size} 个。本任务仅处理这份清单。范围变体在标题库中附带范围说明与编号，专题使用原始标题。</p>${t.scopedRows.map((row,i)=>`<div class="article-item" data-task-scope-row><span class="article-index">${String(i+1).padStart(2,'0')}</span><div class="article-info"><h3>${esc(row.title)}</h3><p>范围：${esc(row.scopeNote||'未补充范围说明')}</p></div></div>`).join('')}`):''}
function taskTypeSwitch(kind,editing=false){return`<div class="type-switch"><a class="radio-card ${kind==='article'?'checked':''}" href="#/task-new?type=article" ${editing?'data-action="task-type-fixed"':''}><strong>${icon('file')}普通文章任务</strong><p>根据标题生成文章正文</p></a><a class="radio-card ${kind==='topic'?'checked':''}" href="#/task-new" ${editing?'data-action="task-type-fixed"':''}><strong>${icon('layers')}专题任务</strong><p>组合已有文章，整理专题页面</p></a></div>`}
function tasksPage(){const rows=state.tasks.filter(t=>state.taskType==='all'||t.kind===state.taskType);return adminShell(`${heading('任务管理','文章与专题在同一个入口管理，各自保留结果与设置。',link('task-new',`${icon('plus')}创建任务`,'btn primary'))}<div class="tabs">${[['all','全部任务'],['article','文章任务'],['topic','专题任务']].map(([v,label])=>btn('task-filter',label,`tab ${state.taskType===v?'active':''}`,`data-value="${v}"`)).join('')}</div><section class="panel"><div class="panel-head"><h2>任务列表</h2>${link('libraries','管理标题库','text-btn')}</div><div class="table-wrap"><table><thead><tr><th>任务名称</th><th>类型</th><th>状态</th><th>本轮进度</th><th>执行间隔</th><th>操作</th></tr></thead><tbody>${rows.map(t=>`<tr><td><a class="row-title" href="#/task-detail?id=${t.id}">${esc(t.name)}</a><div class="row-copy">${esc(state.libraries.find(l=>l.id===t.libraryId)?.name||'标题库已移除')}</div></td><td>${badge(t.kind==='topic'?'专题任务':'文章任务',t.kind==='topic'?'blue':'')}</td><td>${taskStatus(t)}</td><td>${t.results.map(resultSnapshot).filter(r=>['published','draft','pending'].includes(r.status)).length} / ${t.count} 个${t.kind==='topic'?'专题':'文章'}</td><td>每 ${t.interval} 分钟</td><td><div class="row-actions">${link('task-detail','查看详情','text-btn',`id=${t.id}`)}${btn('toggle-task',t.status==='active'?'暂停':'启动','text-btn',`data-id="${t.id}"`)}</div></td></tr>`).join('')}</tbody></table></div></section>`,'tasks','任务管理')}
function taskStatus(t){const labels={active:'运行中',paused:'已暂停',waiting_titles:'等待新标题',complete:'本轮已完成',waiting_ai:'等待模型配置'};return badge(labels[t.status]||'已暂停',t.status==='active'||t.status==='complete'?'green':'amber')}
function taskNewPage(){if(routeInfo().query.has('edit')&&!state.tasks.some(t=>t.id===Number(routeInfo().query.get('edit'))))return emptyResource('没有找到要编辑的任务','从任务列表选择一个可用任务。');const t=taskForm();const isTopic=t.kind==='topic';const editing=state.activeTaskFormKey.startsWith('edit:');const lib=state.libraries.find(l=>l.id===t.libraryId);const sourceRows=taskSourceRows(t,lib);const remaining=sourceRows.filter(row=>!(t.consumed||[]).map(norm).includes(norm(taskRowKey(row,t)))).length;const ret='task-new'+(editing?`?edit=${t.id}`:isTopic?'':'?type=article');return adminShell(`${link('tasks',`${icon('back')}返回任务列表`,'back-link')}${heading(editing?'编辑任务设置':'创建任务',editing?'修改设置后，已有运行结果和进度继续保留。':'先选择类型，再设置标题来源和生成方式。')}${taskTypeSwitch(t.kind,editing)}${!state.aiReady?notice('还没有可用的文本模型','可以先保存为暂停任务，连接后继续启动。','warning',link('ai-settings','配置 AI','btn small',`return=${encodeURIComponent(ret)}`)):''}${lib&&!lib.titles.length?notice('这个标题库还是空的','保存任务不受影响。补充标题后，即可开始生成。','warning',link('library-edit','补充标题','btn small',`id=${lib.id}&use=task&return=${encodeURIComponent(ret)}`)):''}<div class="edit-layout"><div>${scopedTaskPreview(t)}${panel('基本信息',`${field('任务名称',input('task-name',t.name,'填写便于识别的任务名称'))}${formError('task-name')}${field('标题库',select('task-library',[['',t.scopedRows?.length?'保存任务时新建标题库':'请选择可用标题库'],...state.libraries.map(l=>[l.id,l.name])],t.libraryId),`${link('library-edit','新建或导入标题库','text-btn',`new=1&use=task&return=${encodeURIComponent(ret)}`)}`)}${formError('task-library')}<p class="help">${t.scopedRows?.length?`本轮清单有 ${sourceRows.length} 项，尚未处理 ${remaining} 项；${lib?'标题库中其他标题留待原任务使用。':'保存时会建立标题库，不同范围分别绑定可复用的标题库项。'}`:`这个库有 ${lib?.titles.length||0} 个标题，本轮尚未处理 ${remaining||0} 个。`}</p><div class="two-fields">${field(`本轮${isTopic?'专题':'文章'}数量`,input('task-count',t.count,'5','number'),'标题用完时等待补充，已有结果继续保留。')}${field('执行间隔（分钟）',input('task-interval',t.interval,'60','number'))}</div>${formError('task-numbers')}`)}${panel(isTopic?'选文与 AI 规则':'文章生成规则',`${isTopic?field('文章范围',select('task-scope',[['all','全部本站公开文章'],['geo','内容设计相关分类'],['recent','近 7 天公开文章']],t.scope)):''}${field('生成规则',textarea('task-rule',t.rule,'说明内容范围、表达方式与依据。',4))}<div class="actions">${btn('default-task-rule','使用默认规则','text-btn')}</div><div class="two-fields">${field('AI 模型',select('task-model',state.aiReady?['演示文本模型','演示备用模型']:['暂未配置文本模型'],state.aiReady?t.model:'暂未配置文本模型'))}${isTopic?field('专题模板',select('task-layout',[['default','标准聚合'],['guide','阅读指南'],['roundup','资讯盘点']],t.layout)):''}</div>`)}${panel('生成与维护',`${field('生成后',select('task-after',[['auto_publish','自动发布'],['draft','保存为草稿'],['review','提交审核']],t.after))}${isTopic?`${field('遇到已有专题',select('task-repeat',[['skip','跳过重复专题'],['update','更新本任务关联的专题']],t.repeat),'更新范围限定为当前任务已经关联的专题。')}<div class="switch-line"><div><strong>持续维护已生成专题</strong><p>保留人工修改，为来源变化提供更新建议。</p></div>${toggle('task-maintain',t.maintain)}</div>`:''}`)}</div><aside class="sticky"><section class="side-block"><h3>${editing?'更新后的设置':'任务概览'}</h3><div class="side-line"><span>任务类型</span><strong>${isTopic?'专题':'文章'}</strong></div><div class="side-line"><span>标题库</span><strong>${t.scopedRows?.length?new Set(t.scopedRows.map(taskLibraryTitle)).size:lib?.titles.length||0} 个标题</strong></div><div class="divider"></div><p class="help" id="task-summary">每 ${t.interval} 分钟处理${t.scopedRows?.length?'一项主题与范围':'一个标题'}，最多生成 ${t.count} 个${isTopic?'专题':'文章'}。${t.after==='draft'?'结果保存为草稿。':t.after==='review'||isTopic&&state.settings.review?'生成后提交审核。':'生成后自动发布。'}</p>${btn('create-task',editing?'保存并继续运行':'创建并启动','btn primary wide')}<div style="margin-top:10px">${btn('save-task',editing?'保存设置并暂停':'保存为暂停任务','btn wide')}</div><p class="help">原型不会定时调用模型；创建后可点击“执行一次”查看模拟结果。</p></section></aside></div>`,'tasks','任务管理')}
function taskDetailPage(){const t=currentTask();if(!t)return emptyResource('没有找到这个任务','从任务列表选择一个可用任务。');state.activeTaskId=t.id;const lib=state.libraries.find(l=>l.id===t.libraryId);const generated=t.results.map(resultSnapshot).filter(r=>['published','draft','pending'].includes(r.status)).length;const ret=`task-new?edit=${t.id}`;return adminShell(`${link('tasks',`${icon('back')}返回任务列表`,'back-link')}${heading(esc(t.name),`${t.kind==='topic'?'专题任务 · 组合已有文章':'文章任务 · 生成新的文章正文'} · ${esc(lib?.name||'标题库已移除')}`,btn('run-task',`${icon('play')}执行一次`,'btn primary',`data-id="${t.id}" ${t.running?'disabled':''}`)+btn('toggle-task',t.status==='active'?'暂停任务':'启动任务','btn',`data-id="${t.id}"`))}${notice(t.status==='active'?'任务已启动':t.status==='waiting_titles'?'本轮在等待新标题':t.status==='complete'?'设定数量已经完成':t.status==='waiting_ai'?'连接模型后可以继续':'任务已暂停',t.status==='active'?'原型模拟任务状态，可以执行一次查看本任务的结果。':t.status==='waiting_titles'?'这个库的标题已处理完。补充标题后继续，已有结果和人工修改保留。':t.status==='complete'?'可以查看结果，或调整本轮数量继续生成。':'设置与结果已保留。暂停任务会保留已经发布的内容。',t.status==='active'||t.status==='complete'?'success':'warning',t.status==='waiting_titles'?link('library-edit','补充标题','btn small',`id=${t.libraryId}&use=task&return=${encodeURIComponent(ret)}`):t.status==='waiting_ai'?link('ai-settings','连接模型','btn small',`return=${encodeURIComponent(ret)}`):'')}
  <div class="stats">${[['已生成',generated],['已发布',t.results.map(resultSnapshot).filter(r=>r.status==='published').length],['草稿 / 待审核',t.results.map(resultSnapshot).filter(r=>['draft','pending'].includes(r.status)).length],['待补充文章',t.results.map(resultSnapshot).filter(r=>r.status==='waiting').length]].map(([k,v])=>`<div class="stat"><span class="stat-label">${k}</span><strong class="stat-number">${v}</strong></div>`).join('')}</div><div class="edit-layout"><div>${scopedTaskPreview(t)}${panel('本任务生成结果',t.running?'<div class="processing"><span class="spinner"></span><h3>正在处理一个标题</h3><p>完成后显示真实的模拟结果。</p></div>':t.results.length?t.results.map(resultSnapshot).map((r,i)=>`<div class="article-item"><span class="article-index">${String(i+1).padStart(2,'0')}</span><div class="article-info"><h3>${r.topicId?link('edit',esc(r.title),'',`id=${r.topicId}`):r.articleId?link('article',esc(r.title),'',`id=${r.articleId}`):esc(r.title)}</h3>${r.scopeNote?`<p>范围：${esc(r.scopeNote)}</p>`:''}<p>${r.status==='skipped'?'已有同名内容，本轮保留原记录。':r.status==='waiting'?'相关公开文章不足，可以补充后发布。':`${r.count||0} ${t.kind==='topic'?'篇选文':'字，演示正文'} · ${r.message||'本次生成已完成'}`}</p></div>${r.status==='skipped'?badge('重复跳过'):r.status==='failed'?badge('生成失败','red'):statusTag(r.status)}</div>`).join(''):`<div class="empty-state"><div class="empty-icon">${icon('tasks')}</div><h3>这个任务还没有运行结果</h3><p>点击“执行一次”处理第一个标题。</p>${btn('run-task','执行一次','btn primary',`data-id="${t.id}"`)}</div>`)}${panel('执行记录',t.results.length?`<p class="help">本任务已处理 ${t.results.length} ${t.scopedRows?.length?'项主题与范围':'个标题'}，成功生成 ${generated} 个。重复项与待补充项均单独记录。</p>`:'<p class="help">创建与启动均已记录，尚未执行任何标题。</p>')}</div><aside class="sticky"><section class="side-block"><h3>运行设置</h3><div class="side-line"><span>本轮目标</span><strong>${generated} / ${t.count} 个</strong></div><div class="side-line"><span>执行间隔</span><strong>${t.interval} 分钟</strong></div><div class="side-line"><span>当前状态</span>${taskStatus(t)}</div>${t.kind==='topic'?`<div class="side-line"><span>模板</span><strong>${layoutName(t.layout)}</strong></div>`:''}<div class="side-line"><span>生成后</span><strong>${t.after==='draft'?'保存草稿':t.after==='review'?'提交审核':'自动发布'}</strong></div><div class="divider"></div>${link('task-new','编辑本任务设置','btn wide',`edit=${t.id}`)}${link('library-edit','查看本任务标题库','text-btn',`id=${t.libraryId}&use=task&return=${encodeURIComponent(ret)}`)}</section></aside></div>`,'tasks','任务管理')}

function libraryForm(){const q=routeInfo().query;const key=q.has('new')?'new':q.get('id')||'L1';state.activeLibraryKey=key;const lib=state.libraries.find(l=>l.id===key);if(key!=='new'&&!lib)return null;return state.libraryForms[key]??={id:key,name:lib?.name||'',raw:lib?.titles.join('\n')||'',direction:'GEO 内容组织与专题页面',rule:'根据本站文章提出彼此区分的主题标题，说明适合人群和阅读需求。'}}
function librariesPage(){return adminShell(`${heading('标题库','共用标题来源，文章与专题任务分别记录自己的使用进度。',link('library-edit',`${icon('plus')}新建标题库`,'btn primary','new=1'))}<div class="tabs"><a class="tab" href="#" data-action="existing-module" data-name="素材库">素材库</a><span class="tab active">标题库</span></div><section class="panel"><div class="panel-head"><h2>可用标题库</h2>${link('library-edit','导入标题','text-btn','new=1')}</div><div class="table-wrap"><table><thead><tr><th>标题库名称</th><th>不同标题</th><th>使用任务</th><th>最近更新</th><th>操作</th></tr></thead><tbody>${state.libraries.map(l=>`<tr><td><a class="row-title" href="#/library-edit?id=${l.id}">${esc(l.name)}</a><p class="row-copy">${l.titles.length?'可以编辑、导入或生成标题建议':'暂时没有标题，可随时补充'}</p></td><td>${l.titles.length} 个</td><td class="small muted">${state.tasks.filter(t=>t.libraryId===l.id).map(t=>link('task-detail',esc(t.name),'text-btn',`id=${t.id}`)).join('、')||'尚未使用'}</td><td class="tiny muted">${l.updated}</td><td><div class="row-actions">${link('library-edit','编辑','text-btn',`id=${l.id}`)}${link('task-new','创建专题任务','text-btn',`library=${l.id}`)}</div></td></tr>`).join('')}</tbody></table></div></section>`,'library','内容资产')}
function libraryEditPage(){const f=libraryForm();if(!f)return emptyResource('这个标题库暂时无法打开','从标题库列表重新选择。');const q=routeInfo().query;const ret=safeReturn(q.get('return'),q.get('use')==='task'?'task-new':q.get('use')==='batch'?'batch':'topics');const hasReturn=q.has('use');return adminShell(`${link(hasReturn?ret:'libraries',`${icon('back')}${hasReturn?'返回刚才的表单':'返回标题库'}`,'back-link')}${heading(f.id==='new'?'新建标题库':'编辑标题库','输入、导入和 AI 建议都会保留当前名称与标题。',btn('save-library',hasReturn?'保存并返回':'保存标题库','btn primary'))}${!state.aiReady?notice('连接 AI 后可以生成标题建议','手工输入、文件导入和保存均可继续。','warning',link('ai-settings','配置 AI','btn small',`return=${encodeURIComponent('library-edit?'+q.toString())}`)):''}<div class="edit-layout"><div>${panel('标题内容',`${field('标题库名称',input('libraryName',f.name,'例如：GEO 入门专题标题库'))}${formError('library-name')}${field('标题清单',textarea('libraryTitles',f.raw,'每行一个标题',9))}<div class="actions">${btn('import-library',`${icon('upload')}导入 TXT / CSV`)}${btn('suggest-titles',`${icon('spark')}AI 补充标题`)}${btn('download-example','下载标题示例','text-btn')}<input type="file" id="library-file" accept=".txt,.csv" hidden></div><p class="help" id="library-title-count">${titleRows(f.raw).length} 行输入，保存后保留 ${uniqueTitles(f.raw).length} 个不同标题。输入时保留原文，导入和保存时去重。</p>${formError('library-import')}`)}${panel('AI 标题建议',`${field('主题方向',input('title-direction',f.direction,'说明主题、读者或文章范围'))}${field('生成说明',textarea('title-rule',f.rule,'说明标题建议的范围。',3))}${btn('suggest-titles',`${icon('spark')}生成 5 个标题建议`,'btn primary')}<p class="help">建议追加到清单，你可以继续修改，也可以删除。</p>`)} </div><aside class="sticky"><section class="side-block"><h3>使用这些标题</h3><p class="help">标题数量可以按实际需要补充，空库也可以先保存。</p><div class="divider"></div>${btn('library-to-task','保存并创建专题任务','btn primary wide')}<div style="margin-top:10px">${btn('use-library-batch','带到批量新建','btn wide')}</div><p class="help">“带到批量新建”使用当前清单，未保存的标题库会继续保留。</p></section></aside></div>`,'library','内容资产')}
function settingsPage(){const s=state.settingsDraft;const q=routeInfo().query;const ret=q.get('return');return adminShell(`${ret?link(safeReturn(ret),`${icon('back')}返回专题编辑`,'back-link'):''}${heading('专题设置','调整后点击保存，再应用到网站。返回表单时保留尚未保存的修改。',btn('save-settings',ret?'保存并返回':'保存设置','btn primary'))}<div class="tabs"><span class="tab" data-action="existing-module" data-name="网站基本设置" role="button" tabindex="0">网站基本设置</span><span class="tab active">专题</span>${link('templates','前台模板','tab')}</div><div class="edit-layout"><div>${panel('网站入口',`${field('专题栏目名称',input('channel',s.channel,'专题'))}${formError('channel')}<div class="switch-line"><div><strong>在网站导航显示专题</strong><p>进入专题列表继续阅读。</p></div>${toggle('nav',s.nav)}</div><div class="switch-line"><div><strong>在首页显示专题模块</strong><p>展示最近发布的专题。</p></div>${toggle('home',s.home)}</div>${field('首页展示数量',select('homeCount',[['3','3 个'],['6','6 个'],['9','9 个']],s.homeCount))}<div class="actions">${btn('save-preview-home','保存并查看首页','text-btn')}${link('home','查看已保存效果','text-btn')}</div>`)}${panel('默认模板',`${field('新专题默认模板',select('default-layout',[['default','标准聚合'],['guide','阅读指南'],['roundup','资讯盘点']],s.layout))}<p class="help">设置只影响后续新专题，已有专题仍使用各自选择的模板。</p>${link('templates','查看模板','text-btn')}`)}${panel('发布方式',`<div class="switch-line"><div><strong>专题发布进入人工审核</strong><p>开启后使用现有审核中心。已有公开版本会在审核期间继续展示。</p></div>${toggle('review',s.review)}</div><p class="help">默认可直接发布，评分、封面与 FAQ 按需要使用。</p>`)} </div><aside class="sticky"><section class="side-block"><h3>本次设置</h3><p class="help" id="settings-change-status">${JSON.stringify(s)===JSON.stringify(state.settings)?'当前内容与已保存设置一致。':'有尚未保存的修改，前台仍使用已保存设置。'}</p>${btn('discard-settings','恢复已保存设置','btn wide')}<div class="divider"></div>${link('new','新建专题','btn primary wide')}${link('task-new','创建专题任务','text-btn')}</section><section class="side-block"><h3>AI 连接</h3><p class="help">${state.aiReady?'已连接演示文本模型。':'可以先手工整理，连接模型后继续生成。'}</p>${link('ai-settings','查看 AI 设置','text-btn','return=settings')}</section></aside></div>`,'settings','网站设置')}
function workspacePage(){const d=state.chatDraft;return adminShell(`${heading('AI 工作台','描述主题，准备专题草稿后再进入编辑。已有草稿会继续保留。')}<section class="panel"><div class="panel-body chat-area"><div class="chat-message"><div class="chat-label">GEOFlow 助手</div><p>可以把已有文章整理为专题。原型使用本站的 GEO 与 AI 搜索文章，试试“整理一个 AI 搜索入门专题”。</p><div class="actions">${btn('chat-example','整理 AI 搜索入门专题','btn small')}${btn('chat-batch','准备一批 GEO 专题','btn small')}</div></div>${state.chat?`<div class="chat-message user"><div class="chat-label">你</div><p>${esc(state.chatPrompt)}</p></div><div class="chat-message"><div class="chat-label">GEOFlow 助手</div>${!state.aiReady?`<p>目前还没有文本模型，输入已保留。可以配置后继续，或手工创建。</p>${link('ai-settings','配置 AI','btn primary','return=workspace')}${link('new','手工创建','btn')}`:d?`<p>已准备一份演示草稿，从本站文章中选择 ${d.ids.length} 篇，并整理简介与摘要。</p><div class="summary-fact"><strong>${esc(d.title)}</strong><p class="help">${layoutName(d.layout)} · ${d.ids.length} 篇文章 · 生成后仍可修改</p></div>${btn('open-chat-draft',state.newDraft.title?'保存当前新建草稿，再打开这份':'打开这份草稿','btn primary')}`:'<p>这个主题暂未找到相关文章。可以换一个主题，或先手工选择已有文章。</p>'+link('new','手工创建','btn')}</div>`:''}</div><div class="panel-body" style="border-top:1px solid var(--line)"><div class="chat-compose">${input('chat-prompt',state.chatPrompt,'描述你想整理的专题…')}${btn('chat-send',`${icon('spark')}发送`,'btn primary')}</div><p class="help">原型生成仅使用演示文章，正式系统按真实文章范围检索。</p></div></section>`,'workspace','AI 工作台')}
function reviewPage(){const rows=state.topics.filter(t=>t.status==='pending');return adminShell(`${subnav()}${heading('专题待审核','普通专题默认直接发布；开启审核后，在这里处理。',link('settings','查看审核设置'))}${panel('待审核专题',rows.length?rows.map(t=>{const d=t.pendingDraft||candidate(t);return`<div class="article-item"><div class="article-info"><h3>${esc(temporalTitle(d))}</h3><p>${validIds(d.ids).length} 篇选文 · ${t.publicDraft?'更新待审核，旧公开版本仍可阅读':'尚未公开'}</p></div><div class="row-actions">${link('detail','查看待审核版本','btn small',`id=${t.id}&preview=1&review=1`)}${btn('approve-topic','审核并发布','btn primary small',`data-id="${t.id}"`)}</div></div>`}).join(''):`<div class="empty-state"><div class="empty-icon">${icon('check')}</div><h3>专题审核已完成</h3><p>可以返回列表继续创建或维护。</p>${link('topics','返回专题列表','btn primary')}</div>`)}`)}
function historyPage(){const id=Number(routeInfo().query.get('id')||state.editId);const t=getTopic(id);if(!t)return emptyResource('这个专题没有可用的历史记录','从专题列表重新打开。');const versions=state.versions[id]||[];return adminShell(`${link('edit',`${icon('back')}返回专题编辑`,'back-link',`id=${id}`)}${heading('专题历史版本','查看和恢复都限定在当前专题。恢复后先保存为编辑草稿。')}${panel(esc(t.publicDraft?.displayTitle||t.title),versions.length?[...versions].reverse().map((v,i)=>`<div class="version-item"><span class="version-no">${v.key}</span><div class="version-body"><h3>${esc(v.description)}</h3><p>${v.date} · ${v.draft.ids.length} 篇文章 · ${layoutName(v.draft.layout)}</p></div><div class="row-actions">${link('detail','查看版本','text-btn',`id=${id}&version=${v.key}`)}${i===0&&t.publicDraft?badge('当前公开版','green'):btn('restore-version','恢复为草稿','btn small',`data-id="${id}" data-version="${v.key}"`)}</div></div>`).join(''):`<div class="empty-state"><h3>这个专题还没有发布版本</h3><p>发布后，历史版本会记录本专题当时的内容与选文。</p>${link('edit','继续编辑','btn primary',`id=${id}`)}</div>`)}`)}
function trashPage(){return adminShell(`${subnav()}${heading('专题回收站','恢复为草稿，选文与设置保留；重新发布由你决定。')}${panel('已移入回收站',state.trash.length?state.trash.map(t=>`<div class="article-item"><div class="article-info"><h3>${esc(t.title)}</h3><p>${t.date} 移入 · ${t.ids.length} 篇关联文章仍保留</p></div>${btn('restore-topic','恢复为草稿','btn small',`data-id="${t.id}"`)}</div>`).join(''):`<div class="empty-state"><h3>回收站为空</h3><p>已恢复的专题可以在列表继续编辑。</p>${link('topics','返回专题列表','btn primary')}</div>`)}`)}
function scenariosPage(){return adminShell(`${heading('异常与引导状态','选择一个演示场景，在当前专题中查看问题与下一步。')}<div class="scenario-grid">${[['missing-ai','没有配置 AI','保留已填内容，手工整理可以继续。','配置并返回'],['no-articles','相关公开文章不足','保留草稿，提供选文与调整范围入口。','补充文章'],['timeout','AI 请求超时','保留当前内容，重试仅处理这次请求。','重试生成'],['conflict','AI 建议与人工文字相遇','先对照当前文字与建议，再决定采用。','查看建议'],['withdrawn','来源文章已撤回','停止公开展示该文章及相关事实，选择有效替代。','查看影响']].map(([id,title,desc,action])=>`<section class="scenario-card"><div class="eyebrow">${icon(id==='missing-ai'?'settings':'alert')} 原型场景</div><h2>${title}</h2><p>${desc}</p>${btn('scenario',action,'btn primary',`data-scenario="${id}"`)}</section>`).join('')}<section class="scenario-card"><div class="eyebrow">${icon('file')} 首次使用</div><h2>尚未创建专题</h2><p>清楚说明文章组合方式，并提供新建与自动化入口。</p>${link('empty','体验空列表','btn primary')}</section></div>${notice('演示状态会保留到本次体验结束','需要重新比较初始状态时，可点击顶部“重置体验”。')}`)}
function templatePreviewPage(){const q=routeInfo().query;const layout=validLayout(q.get('layout')||state.settings.layout);const isDraft=q.has('draft');const id=q.get('id')||state.editId||101;return`${prototypeBar('template-preview')}<div class="preview-strip"><div><strong>模板预览</strong><span class="muted small">同一份内容，只切换阅读布局</span></div><div class="actions">${select('preview-layout',[['default','标准聚合'],['guide','阅读指南'],['roundup','资讯盘点']],layout)}${btn('apply-preview-template',isDraft?'用于当前专题':'设为新专题默认模板','btn primary',`data-layout="${layout}"`)}${link(isDraft?previewEditorRoute():'templates','返回','btn')}</div></div>${frontDetail(layout,true,isDraft,Number(id))}`}

function frontDetail(layout='default',embedded=false,draftMode=false,explicitId=null){
  const q=routeInfo().query;draftMode=draftMode||q.has('draft');
  const id=explicitId??Number(q.get('id')||(embedded?101:layout==='guide'?102:layout==='roundup'?103:101));
  const t=getTopic(id);
  if(!draftMode&&!t)return emptyResource('这个专题暂时无法打开','它可能尚未在当前窗口创建，或已移入回收站。可以浏览现有公开专题。',true);
  if(draftMode&&!previewDraft())return emptyResource('这份草稿暂时无法打开','返回专题列表重新选择要预览的内容。',true);const draftBack=previewEditorRoute();let d=draftMode?clone(previewDraft()):clone(q.has('review')&&t.pendingDraft?t.pendingDraft:q.has('preview')?candidate(t):t.publicDraft||candidate(t));
  const version=q.get('version');if(version){const v=state.versions[id]?.find(v=>v.key===version);if(!v)return emptyResource('没有找到这个历史版本','从当前专题的历史记录重新选择。',true);d=clone(v.draft)}
  if(!draftMode&&!q.has('preview')&&!embedded&&!version&&!t.publicDraft)return emptyResource('这个专题还没有公开','可以从专题列表预览草稿，或继续浏览已发布内容。',true);
  const title=draftMode||q.has('preview')?temporalTitle(d):d.displayTitle||temporalTitle(d);
  const chosen=validIds(d.ids).map(id=>articles.find(a=>a.id===id));if(!draftMode&&!q.has('preview')&&!embedded&&!version&&chosen.length<2)return emptyResource('这个专题暂时暂停公开','有效来源文章需要补充。原草稿和已完成内容继续保留，可先浏览其他专题。',true);
  const names=[...new Set(chosen.map(a=>d.groups?.[a.id]&&d.groups[a.id]!=='不分组'?d.groups[a.id]:'相关阅读'))];
  const grouped=names.map(name=>({name,items:chosen.filter(a=>(d.groups?.[a.id]&&d.groups[a.id]!=='不分组'?d.groups[a.id]:'相关阅读')===name)}));
  const preview=embedded||draftMode||q.has('preview');
  const displayDate=d.updatedAt||'2026.09.30';
  const content=`${preview?`<div class="notice"><div><strong>${draftMode?'草稿预览':embedded?'模板预览':'专题预览'}</strong><p>当前展示演示内容，预览操作不会写入正式网站。</p></div>${!embedded?link(draftMode?draftBack:'edit','返回编辑','btn small',!draftMode?`id=${t.id}`:''):''}</div>`:''}${version?notice(`历史版本 ${esc(version)}`,'展示该版本的文章数量与导读。恢复后会进入编辑草稿。'):''}<div class="breadcrumbs">${link('home','首页','')}<span>/</span>${link('channel',esc(state.settings.channel),'')}<span>/</span>${layoutName(layout)}</div>
  <section class="front-hero"><div class="front-kicker">GEOFlow · ${layout==='guide'?'READING GUIDE':layout==='roundup'?'MONTHLY COLLECTION':'TOPIC COLLECTION'}</div><h1>${esc(title)}</h1><p class="lead">${esc(d.intro||'为这个专题补充一段简介，说明范围和适合人群。')}</p><div class="actions">${chosen[0]?link('article',`开始阅读 ${icon('arrow')}`,'btn navy',`id=${chosen[0].id}`):preview?link(draftBack,'返回编辑，选择文章','btn navy'):''}${preview?link(draftMode?draftBack:'edit','继续编辑','btn',!draftMode?`id=${t.id}`:''):btn('copy-link',`${icon('link')}复制演示链接`)}</div></section>
  <div class="front-facts"><div class="front-fact"><strong>${chosen.length} 篇</strong><span>公开文章，按主题整理</span></div><div class="front-fact"><strong>${layoutName(layout)}</strong><span>阅读方式</span></div><div class="front-fact"><strong>${displayDate}</strong><span>${preview?'草稿整理日期（演示）':'内容更新日期'}</span></div><div class="front-fact"><strong>${d.score?'8.5 / 10':d.generated?'AI 辅助整理':'手工整理'}</strong><span>${d.score?'AI 辅助评分，原型演示':'来源与整理说明可查'}</span></div></div>
  <div class="front-detail"><div class="front-content"><section class="front-section quick-summary"><div class="front-kicker">AT A GLANCE</div><h2>一分钟理解这个专题</h2><div class="answer-box"><span class="answer-label">核心结论</span><p>${esc(d.one||d.intro||'这份草稿的摘要还没有填写，可以返回编辑补充。')}</p></div>${d.scopeNote?.trim()?`<div class="summary-fact"><strong>适用范围与限制</strong><p>${esc(d.scopeNote)}</p></div>`:''}${(d.generated?facts.filter(f=>validIds(d.ids).includes(f.source)):[]).map((f,i)=>`<div class="fact-point"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${f.title}</h3><p>${f.text}</p>${link('article',`依据：${esc(articles.find(a=>a.id===f.source).title)}`,'source-ref',`id=${f.source}`)}</div></div>`).join('')}</section>
  ${layout==='guide'?`<section class="guide-band"><span class="front-kicker">YOUR READING PATH</span><h2>按阅读阶段，建立完整认识。</h2><p>可先读摘要，再按实际需要深入原文。每个分组都保留对应的公开文章。</p><div class="actions">${grouped.map((g,i)=>`<a class="btn small" href="#section-${i}" data-action="scroll-group" data-index="${i}">0${i+1} ${esc(g.name)}</a>`).join('')}</div></section>`:layout==='roundup'?`<section class="guide-band"><span class="roundup-date">${displayDate.slice(0,7)}</span><h2>这次整理，聚焦内容实践。</h2><p>整理日期：${displayDate}。按时间回顾本站文章；标题仍采用这个专题自己的时效设置。</p></section>`:''}
  ${grouped.map((g,i)=>`<section class="front-section" id="section-${i}"><div class="front-section-head"><div><span class="front-kicker">${layout==='guide'?`STEP 0${i+1}`:layout==='roundup'?`COLLECTION 0${i+1}`:`SECTION 0${i+1}`}</span><h2>${esc(g.name)}</h2></div><span class="muted small">${g.items.length} 篇</span></div>${g.items.map((a,k)=>`<article class="front-article"><span class="front-article-num">${String(chosen.indexOf(a)+1).padStart(2,'0')}</span><div><div class="eyebrow">${esc(a.category)}${layout==='roundup'?` · ${a.date}`:''}</div><h3><a href="#/article?id=${a.id}">${esc(a.title)}</a></h3><p>${esc(a.excerpt)}</p><div class="small muted">${layout==='guide'?(['先理解概念与范围','再学习组织与表达','最后检查发布与来源'][i]||'按需要继续深入这个分组。'):'推荐理由：补充这个主题的具体做法。'}</div></div>${link('article',icon('arrow'),'icon-btn',`id=${a.id}`)}</article>`).join('')}</section>`).join('')||`<div class="empty-state"><h3>还没有选择文章</h3><p>回到编辑页补充选文。</p></div>`}
  <section class="front-section"><h2>关于这个专题</h2><p class="muted">由 GEOFlow 演示站整理，文章保留独立地址。这个专题的简介、分组和摘要用于连接内容；关键事实可以继续查看原文。</p>${link('channel',`浏览其他专题 ${icon('arrow')}`,'text-btn')}</section></div><aside class="front-sidebar"><details class="reading-information" ${innerWidth>=760?'open':''}><summary>查看评分、时间与来源信息 ${icon('down')}</summary><div>${d.score?scoreCard():''}<section class="info-card"><h2>基础信息</h2>${[['适合人群','内容运营、网站负责人、GEO 从业者'],['专题范围',d.scopeNote||'AI 搜索中的内容组织'],['文章数量',`${chosen.length} 篇公开文章`],['首次发布',d.publishedAt||'尚未发布'],['公开更新',preview?'发布后记录':d.updatedAt||'尚未发布'],['内容复核','本原型未执行真实复核'],['技术检查','本原型未执行线上检查']].map(([k,v])=>`<div class="info-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}</section>${d.tags?.trim()?`<section class="info-card"><h2>标签</h2>${frontTags(d.tags)}</section>`:''}<section class="info-card"><h2>来源与整理</h2><p class="review-copy">整理：GEOFlow 演示编辑<br>方式：组合本站公开文章<br>整理方式：${d.generated?'AI 辅助选文、导读与摘要':'手工选文与编排'}</p><p class="review-copy">原型内容用于体验信息层级。评分、身份和复核状态均有演示说明。</p>${chosen[0]?link('article','查看公开原文','text-btn',`id=${chosen[0].id}`):''}</section></div></details></aside></div>`;
  return embedded?`<div class="front">${frontHeader()}<main class="front-main" id="main-content">${content}</main>${frontFooter()}</div>`:frontShell(content,layout==='guide'?'guide':layout==='roundup'?'roundup':'detail');
}

function articlePage(){const requested=Number(routeInfo().query.get('id')||202);if(state.unavailable.has(requested))return emptyResource('这篇文章已撤回','本站已停止展示这篇文章，所属专题也会隐藏对应选文与事实。可以继续浏览其他内容。',true);if(!articles.some(a=>a.id===requested))return emptyResource('没有找到这篇文章','请从专题的公开选文重新进入。',true);const a=articles.find(x=>x.id===requested);if(!isPublicArticle(a))return emptyResource('这篇文章还没有公开','这是文章任务保存的草稿或待审核版本。公开选文只使用已发布文章。',true);const related=featuredTopics().filter(t=>t.ids.includes(a.id));return frontShell(`<div class="breadcrumbs">${link('home','首页','')}<span>/</span>${esc(a.category)}<span>/</span>文章</div><article class="article-reading"><header><div class="front-kicker">${a.category.toUpperCase()}</div><h1>${esc(a.title)}</h1><div class="article-meta"><span>GEOFlow 演示编辑</span><time>${a.date}</time><span>预计阅读 5 分钟</span></div><p class="lead">${esc(a.excerpt)}</p></header><div class="answer-box"><span class="answer-label">文章摘要</span><p>围绕实际阅读问题组织内容，说明适用条件、信息来源和下一步可以阅读的材料。</p></div><div class="prose"><h2>从一个明确的问题开始</h2><p>文章标题帮助读者判断主题，摘要进一步说明核心结论和适用范围。正文提供具体做法，让读者知道这些结论的依据。</p><p>在专题中，这篇文章保留原有内容与地址，同时成为某个阅读阶段的一部分。读者可以从摘要进入原文，也可以沿着所属专题继续阅读。</p><h2>把内容组织得更清楚</h2><p>使用具体的小标题，说明信息来自哪里。涉及评分、时间和覆盖范围时，保留真实口径；有变化时更新相关内容。</p><p>这是原型演示文章，用于体验文章与专题之间的双向连接。</p></div><section class="article-related"><span class="front-kicker">IN THIS TOPIC</span><h2>这篇文章也在这些专题中</h2>${related.length?related.map(t=>`<a href="#/${t.layout==='guide'?'guide':t.layout==='roundup'?'roundup':'detail'}?id=${t.id}"><strong>${esc(t.title)}</strong><span>${t.ids.length} 篇文章 ${icon('arrow')}</span></a>`).join(''):`<p class="muted">可以从专题列表发现更多阅读主题。</p>${link('channel','浏览专题','btn navy')}`}</section></article>`,'article')}


const renderers={overview,topics:topicsPage,new:()=>editorPage(true),edit:()=>editorPage(false),select:selectionPage,batch:batchPage,'batch-results':batchResultsPage,tasks:tasksPage,'task-new':taskNewPage,'task-detail':taskDetailPage,libraries:librariesPage,'library-edit':libraryEditPage,settings:settingsPage,templates:templatesPage,'template-preview':templatePreviewPage,'ai-settings':aiSettingsPage,workspace:workspacePage,review:reviewPage,history:historyPage,trash:trashPage,empty:()=>topicsPage(true),scenarios:scenariosPage,home:homePage,channel:channelPage,detail:()=>frontDetail('default'),guide:()=>frontDetail('guide'),roundup:()=>frontDetail('roundup'),article:articlePage};
function render(){const route=routeInfo().route;const y=scrollY;state.detailOpen??={};if(state.renderedHash){state.detailOpen[state.renderedHash]=Object.fromEntries([...document.querySelectorAll('details')].map(d=>[d.querySelector('summary')?.textContent.trim()+(d.classList.contains('reading-information')?`|${state.renderedNarrow?'mobile':'desktop'}`:''),d.open]))}const focusId=document.activeElement?.id;const same=state.renderedHash===location.hash;document.getElementById('app').innerHTML=(renderers[route]||overview)();document.title=`${pages.find(p=>p[0]===route)?.[1]||'原型总览'} · GEOFlow v2.5 交互原型`;state.renderedHash=location.hash;state.renderedNarrow=innerWidth<760;for(const d of document.querySelectorAll('details')){const v=state.detailOpen[location.hash]?.[d.querySelector('summary')?.textContent.trim()+(d.classList.contains('reading-information')?`|${state.renderedNarrow?'mobile':'desktop'}`:'')];if(v!==undefined)d.open=v}if(same&&focusId)document.getElementById(focusId)?.focus({preventScroll:true});document.body.classList.toggle('front-view',['home','channel','detail','guide','roundup','article','template-preview'].includes(route));document.querySelector('main')?.setAttribute('tabindex','-1');document.querySelectorAll('input,select,textarea').forEach(el=>{if(el.id==='title'&&state.errors[targetKey()]?.title){el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby','title-error')}});window.scrollTo(0,y)}
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function matchingArticles(title,scope='all'){let rows=articles.filter(a=>isPublicArticle(a)&&!state.unavailable.has(a.id));if(scope==='geo')rows=rows.filter(a=>a.category==='内容设计');if(scope==='recent')rows=rows.filter(a=>a.date>='2026.09.24');const hints=[['自动|维护|任务','自动化'],['来源|评分|摘要','内容设计'],['技术|内链|Sitemap','技术接入'],['时效|标题|时间','时效管理'],['观察|引用|验证','效果观察']];const hint=hints.find(([pattern])=>new RegExp(pattern,'i').test(title));if(!/GEO|AI|搜索|专题|内容|文章|摘要|来源|评分|标题|时效|自动|维护|内链|技术|阅读|引用|验证/i.test(title))return[];if(hint)rows.sort((a,b)=>Number(b.category===hint[1])-Number(a.category===hint[1]));return rows.slice(0,8).map(a=>a.id)}
function validateDraft(d,forPublish=false){const errors={};if(!d?.title.trim())errors.title='填写专题标题，便于继续整理。';if(forPublish){if(!d.intro.trim())errors.intro='补充准确导读，说明专题范围与适合人群。';if(validIds(d.ids).length<2)errors.articles='需要两篇不同的公开文章，才能组成专题。'}return errors}
function publishRecord(t,d,keepWorking=false){const working=clone(candidate(t));const published=clone(d);published.ids=validIds(published.ids);published.displayTitle=temporalTitle(published);published.publishedAt=t.publicDraft?.publishedAt||'2026.09.30';published.updatedAt='2026.09.30';published.saved=true;t.publicDraft=published;Object.assign(t,{title:published.displayTitle,intro:published.intro,ids:[...published.ids],count:published.ids.length,layout:published.layout,status:'published',date:'09.30 10:30'});delete t.pendingDraft;state.drafts[t.id]=keepWorking?working:clone(published);const versions=state.versions[t.id]??=[];versions.push({key:`v${versions.length+1}`,date:'2026.09.30',description:versions.length?'发布内容更新':'首次发布',draft:clone(published)})}
function saveTopic(forPublish=false){const key=targetKey();const d=draft();const errors=validateDraft(d,forPublish);if(Object.keys(errors).length){state.errors[key]=errors;render();document.getElementById(errors.title?'title':errors.intro?'intro':'articles-error')?.scrollIntoView({block:'center'});document.getElementById(errors.title?'title':errors.intro?'intro':'articles-error')?.focus();notify('输入已保留，按页面标记补充后继续。');return false}
  const duplicate=state.topics.find(t=>t.id!==(state.editorKind==='edit'?state.editId:null)&&recordTopicKey(t)===topicKey(d));const archived=state.trash.find(t=>recordTopicKey(t)===topicKey(d));if(duplicate||archived){state.errors[key]={title:archived?'这个主题和范围已在回收站，请从回收站明确恢复。':'已有同名且范围一致的专题。可返回列表编辑原专题，或填写不同的适用范围。'};render();document.getElementById('title')?.focus();return false}delete state.errors[key];const wasNew=state.editorKind==='new';let t=wasNew?null:getTopic(state.editId);if(!t){const id=Math.max(110,...state.topics.map(t=>t.id),...state.trash.map(t=>t.id))+1;t={id,title:d.title,intro:d.intro,ids:[...d.ids],count:d.ids.length,layout:d.layout,status:'draft',source:'人工整理',date:'09.30 10:30',publicDraft:null};state.topics.unshift(t)}d.saved=true;state.drafts[t.id]=d;
  if(forPublish){if(state.settings.review){t.pendingDraft=clone(d);t.status='pending'}else publishRecord(t,d)}else if(!t.publicDraft){Object.assign(t,{title:d.title,intro:d.intro,ids:[...d.ids],count:d.ids.length,layout:d.layout});if(t.status!=='pending')t.status='draft'}
  if(wasNew){if(state.previewTargets?.[d.previewKey])state.previewTargets[d.previewKey].topicId=t.id;if(state.suggestions.new){state.suggestions[`topic:${t.id}`]=state.suggestions.new;delete state.suggestions.new}const g=state.generations.new;if(g){delete state.generations.new;g.key=`topic:${t.id}`;state.generations[g.key]=g}state.newDraft=newDraft()}
  state.editId=t.id;state.editorKind='edit';if(forPublish){state.filter='all';state.search='';state.selected.clear();go('topics');notify(state.settings.review?'已提交这个版本，旧公开内容继续保留。':'专题已发布，可以查看前台。')}else{go('edit',`id=${t.id}`);notify('草稿已保存，公开内容继续使用已发布版本。')}return t;
}
function addGeneratedTopic(title,status,ids,source,layout='default',scopeNote=''){const d=newDraft(title,ids,layout);d.scopeNote=scopeNote;d.generated=true;d.saved=true;const id=Math.max(110,...state.topics.map(t=>t.id),...state.trash.map(t=>t.id))+1;const t={id,title,intro:d.intro,ids:[...ids],count:ids.length,layout,status,source,date:'09.30 10:30',publicDraft:null};state.topics.unshift(t);state.drafts[id]=d;if(status==='published')publishRecord(t,d);if(status==='pending')t.pendingDraft=clone(d);return id}
function outcome(after,review=state.settings.review){return after==='draft'?'draft':after==='review'||review?'pending':'published'}
async function generate(){const key=targetKey();const d=draft();if(!d||state.generations[key])return;const errors=validateDraft(d);if(Object.keys(errors).length){state.errors[key]=errors;render();document.getElementById('title')?.focus();return}if(!state.aiReady){render();notify('可以先手工选文，连接 AI 后继续。');return}if(state.scenario==='timeout'&&state.scenarioTarget===key){render();notify('这次演示模拟了超时，点击“重新生成”继续。');return}
  const ctx={id:++state.generationSeq,key,d,cancelled:false,phase:'正在选择相关文章'};state.generations[key]=ctx;render();for(const phase of['正在选择相关文章','正在整理阅读顺序','正在补充导读与摘要']){ctx.phase=phase;if(state.generations[ctx.key]!==ctx||ctx.cancelled)return;const h=document.querySelector('#generation-progress h3');if(h&&targetKey()===ctx.key)h.textContent=phase;await delay(260)}if(ctx.cancelled)return;
  if(!validIds(d.ids).length)d.ids=matchingArticles(d.title);d.groups??={};for(const id of d.ids)d.groups[id]??=articles.find(a=>a.id===id)?.group||'相关阅读';if(!d.ids.length){d.articleNotice='本站演示文章尚未找到这个主题的匹配内容。调整标题，或手工选择相关文章。'}else{delete d.articleNotice;if(!d.intro||!d.protect)d.intro=defaultIntro;if(!d.one||!d.protect)d.one='按主题、阅读阶段与事实来源组织已有文章，帮助读者继续理解内容。';else state.suggestions[ctx.key]={one:'围绕文章的实际内容，组织阅读路径，并保留事实依据与更新时间。'};d.generated=true;if(!d.tags)d.tags='GEO,AI 搜索,内容组织'}
  delete state.generations[ctx.key];if(['new','edit'].includes(routeInfo().route)&&targetKey()===ctx.key)render();notify(d.ids.length?'已整理草稿，人工文字保留；有建议时可单独查看。':'尚未找到匹配文章，草稿与输入已保留。');
}
async function startBatch(){const f=clone(state.batchForm);let rowsInput;try{rowsInput=batchRows(f.raw,f.scope,f.scopeNote)}catch(error){state.errors['batch-import']=error.message;render();return}if(!rowsInput.length){state.errors['batch-import']='输入或导入至少一个标题，继续批量整理。';render();document.getElementById('batchInput')?.focus();return}if(!state.aiReady){notify('先连接 AI，或用单个专题手工整理。');go('ai-settings','return=batch');return}const id=state.batches.length+1;const b={id,form:{...f,reviewAtStart:state.settings.review},rows:rowsInput.map(row=>({...row,status:'queued',count:0})),running:true,done:0,cancelled:false};state.batches.push(b);state.activeBatchId=id;go('batch-results',`batch=${id}`);await delay(80);const seen=new Map();
  for(let i=0;i<b.rows.length;i++){const r=b.rows[i];if(b.cancelled){r.status='cancelled';b.done++;continue}const canonical=topicKey(r);const existing=state.topics.find(t=>recordTopicKey(t)===canonical);const archived=state.trash.find(t=>recordTopicKey(t)===canonical);if(archived){r.status='skipped';r.message='同主题已移入回收站，保留停止公开状态。'}else if(seen.has(canonical)){const original=seen.get(canonical);r.status='skipped';r.duplicateOf=original;const first=b.rows[original];r.id=first.id;r.count=first.count||0}else if(existing){r.status='skipped';r.id=existing.id;r.count=validIds(candidate(existing).ids).length;seen.set(canonical,i)}else{seen.set(canonical,i);await delay(140);if(b.cancelled){r.status='cancelled'}else if(state.trash.some(t=>recordTopicKey(t)===canonical)){r.status='skipped';r.message='同主题已移入回收站，保留停止公开状态。'}else if(state.topics.some(t=>recordTopicKey(t)===canonical)){const original=state.topics.find(t=>recordTopicKey(t)===canonical);r.status='skipped';r.id=original.id;r.count=validIds(candidate(original).ids).length}else if(f.simulation==='partial'&&i===3){r.status='failed'}else{const ids=f.simulation==='partial'&&i===4?[209].filter(x=>!state.unavailable.has(x)):matchingArticles(r.title,f.scope);r.status=ids.length<2?'waiting':outcome(f.after,b.form.reviewAtStart||state.settings.review);r.count=ids.length;r.id=addGeneratedTopic(r.title,r.status,ids,'批量生成',f.layout,r.scopeNote)}}b.done++;if(routeInfo().route==='batch-results'&&currentBatch()?.id===id)render()}
  b.running=false;if(routeInfo().route==='batch-results'&&currentBatch()?.id===id)render();notify(b.cancelled?'本批已停止，已完成结果与剩余标题保留。':'本批处理完成，每个标题的结果已经保留。');
}
async function retryBatch(index,batchId=state.activeBatchId){const b=state.batches.find(b=>b.id===Number(batchId));const r=b?.rows[index];if(!r||r.status!=='failed'||r.retrying)return false;r.retrying=true;render();await delay(250);const canonical=topicKey(r);const existing=state.topics.find(t=>recordTopicKey(t)===canonical);const archived=state.trash.find(t=>recordTopicKey(t)===canonical);if(existing){r.status='skipped';r.id=existing.id;r.count=validIds(candidate(existing).ids).length;r.message='同主题已生成，本次保留原结果。'}else if(archived){r.status='skipped';r.message='同主题已移入回收站，保留停止公开状态。';delete r.id}else{const ids=matchingArticles(r.title,b.form.scope);r.status=ids.length<2?'waiting':outcome(b.form.after,b.form.reviewAtStart||state.settings.review);r.count=ids.length;r.id=addGeneratedTopic(r.title,r.status,ids,'批量生成',b.form.layout,r.scopeNote)}r.retrying=false;for(const dup of b.rows){if(dup.duplicateOf===index){dup.id=r.id;dup.count=r.count}}if(routeInfo().route==='batch-results'&&currentBatch()?.id===b.id)render();notify('这一项已重新处理，模板、规则与处理方式沿用本批设置。');return true}
const taskKeys=['kind','name','libraryId','scope','rule','model','count','interval','after','layout','repeat','maintain','scopedRows'];
function saveTask(start){if(routeInfo().route!=='task-new')return;const f=taskForm();if(!state.libraries.some(l=>l.id===f.libraryId)&&!f.scopedRows?.length){state.errors['task-library']='选择一个可用标题库，再保存任务。';render();return}delete state.errors['task-library'];if(!f.name.trim()){state.errors['task-name']='填写任务名称，便于识别运行结果。';render();return}if(!Number.isInteger(Number(f.count))||f.count<1||!Number.isInteger(Number(f.interval))||f.interval<1){state.errors['task-numbers']='生成数量与执行间隔需要填写大于 0 的整数。';render();return}delete state.errors['task-name'];delete state.errors['task-numbers'];if(f.scopedRows?.length){let library=state.libraries.find(l=>l.id===f.libraryId);if(!library){library={id:'L'+(Math.max(0,...state.libraries.map(l=>Number(l.id.slice(1))))+1),name:f.name.trim()+' 标题库',titles:[],updated:'2026.09.30'};state.libraries.push(library);f.libraryId=library.id}library.titles=uniqueTitles([...library.titles,...f.scopedRows.map(taskLibraryTitle)].join('\n'))}document.querySelectorAll('[data-action="save-task"],[data-action="create-task"]').forEach(b=>b.disabled=true);const editing=state.activeTaskFormKey.startsWith('edit:');let t=editing?state.tasks.find(t=>t.id===f.id):null;if(!t){t={id:Math.max(0,...state.tasks.map(t=>t.id))+1,results:[],consumed:[]};state.tasks.unshift(t)}t.operationVersion=(t.operationVersion||0)+1;for(const k of taskKeys)t[k]=clone(f[k]);t.count=Number(t.count);t.interval=Number(t.interval);const lib=state.libraries.find(l=>l.id===t.libraryId);t.status=!start?'paused':!state.aiReady?'waiting_ai':!lib?.titles.length?'waiting_titles':'active';state.activeTaskId=t.id;if(!editing)delete state.taskForms[state.activeTaskFormKey];else state.taskForms[state.activeTaskFormKey]=clone(t);go('task-detail',`id=${t.id}`);notify(editing?'设置已更新，运行结果与进度保留。':start?'任务已创建，可点击“执行一次”查看模拟结果。':'已保存为暂停任务，尚未执行标题。')}
async function runTask(id){const t=state.tasks.find(t=>t.id===Number(id));if(!t||t.running)return;if(!state.aiReady){t.status='waiting_ai';render();return}const done=t.results.map(resultSnapshot).filter(r=>['published','draft','pending'].includes(r.status)).length;if(done>=t.count){t.status='complete';render();notify('本轮目标已完成，可以调整数量后继续。');return}const lib=state.libraries.find(l=>l.id===t.libraryId);const used=new Set(t.consumed.map(norm));const sourceRow=taskSourceRows(t,lib).find(row=>!used.has(norm(taskRowKey(row,t))));const title=sourceRow?.title;if(!title){t.status='waiting_titles';render();notify('标题已经处理完，补充标题后继续；已有结果保留。');return}const config=clone(t);const epoch=t.operationVersion||0;t.running=true;render();await delay(350);if((t.operationVersion||0)!==epoch){t.running=false;if(routeInfo().route==='task-detail'&&currentTask()?.id===t.id)render();notify('本次生成已停止，标题和已完成结果保留，可以再次执行。');return}const canonical=topicKey(sourceRow);const existing=t.kind==='topic'?state.topics.find(x=>recordTopicKey(x)===canonical):null;const archived=t.kind==='topic'?state.trash.find(x=>recordTopicKey(x)===canonical):null;const r={title,count:0,scopeNote:sourceRow.scopeNote||''};if(archived){r.status='skipped';r.message='此前移入回收站，本任务保留停止公开状态。'}else if(existing&&(config.repeat!=='update'||existing.taskId!==t.id)){r.status='skipped';r.topicId=existing.id;r.message='已有同名专题，本轮保留原内容。'}else if(t.kind==='article'){const articleId=Math.max(400,...articles.map(a=>a.id))+1;r.status=config.after==='draft'?'draft':config.after==='review'?'pending':'published';articles.push({id:articleId,title,status:r.status,category:'任务生成',date:'2026.09.30',excerpt:'由文章任务生成的演示文章，保留独立文章地址。',group:'相关阅读'});r.articleId=articleId;r.count=220}else{const ids=matchingArticles(title,config.scope);r.status=ids.length<2?'waiting':outcome(config.after);r.count=ids.length;if(existing){const d=candidate(existing);if(!d.protect){d.ids=ids;d.generated=true}if(r.status==='published')publishRecord(existing,d);else if(r.status==='pending'){existing.pendingDraft=clone(d);existing.status='pending'}r.topicId=existing.id}else{r.topicId=addGeneratedTopic(title,r.status,ids,t.name,config.layout,sourceRow.scopeNote);getTopic(r.topicId).taskId=t.id}}
  t.results.push(r);t.consumed.push(taskRowKey(sourceRow,config));t.running=false;if(t.results.map(resultSnapshot).filter(r=>['published','draft','pending'].includes(r.status)).length>=t.count)t.status='complete';if(routeInfo().route==='task-detail'&&currentTask()?.id===t.id)render();notify(r.status==='skipped'?'已记录重复项，原有内容保留。':r.status==='waiting'?'已保存待补充文章的草稿，其他标题可以继续。':'本任务完成了一次模拟生成。');
}
function saveLibrary(returnAfter=true){const f=libraryForm();if(!f)return null;if(!f.name.trim()){state.errors['library-name']='填写标题库名称，任务就能清楚选择这个库。';render();document.getElementById('libraryName')?.focus();return null}if(state.libraries.some(l=>l.id!==f.id&&norm(l.name)===norm(f.name))){state.errors['library-name']='已有同名标题库，换一个名称或返回列表编辑原库。';render();return null}delete state.errors['library-name'];let lib=state.libraries.find(l=>l.id===f.id);if(!lib){lib={id:'L'+(Math.max(...state.libraries.map(l=>Number(l.id.slice(1))))+1)};state.libraries.push(lib)}Object.assign(lib,{name:f.name.trim(),titles:uniqueTitles(f.raw),updated:'2026.09.30'});if(f.id==='new'){delete state.libraryForms.new;state.libraryForms[lib.id]={...f,id:lib.id,raw:lib.titles.join('\n')}}else f.raw=lib.titles.join('\n');const q=routeInfo().query;if(q.get('use')==='task'){const ret=safeReturn(q.get('return'),'task-new');const key=ret.includes('edit=')?'edit:'+new URLSearchParams(ret.split('?')[1]).get('edit'):ret.includes('article')?'new:article':'new:topic';state.taskForms[key]??=makeTaskForm(ret.includes('article')?'article':'topic');state.taskForms[key].libraryId=lib.id;if(returnAfter)go(ret)}else if(q.get('use')==='batch'){state.batchForm.raw=lib.titles.join('\n');if(returnAfter)go('batch')}else if(returnAfter)go('libraries');notify(`${lib.titles.length} 个不同标题已保存${q.has('use')?'，已返回原表单':''}。`);return lib}
function saveSettings(){if(!state.settingsDraft.channel.trim()){state.errors.channel='填写栏目名称，便于网站导航识别。';render();return false}delete state.errors.channel;state.settings=clone(state.settingsDraft);if(!state.newDraft.title)state.newDraft.layout=state.settings.layout;render();notify('设置已保存，网站前台现在使用这一版设置。');return true}

function updateSelectionControls(){const checks=[...document.querySelectorAll('[data-field="topic-check"]')];const count=checks.filter(c=>c.checked).length;const all=document.querySelector('[data-field="all-topics"]');if(all){all.checked=count>0&&count===checks.length;all.indeterminate=count>0&&count<checks.length}const label=document.getElementById('selected-count');if(label)label.textContent=`已选 ${count} 个`;const button=document.querySelector('[data-action="bulk-publish"]');if(button)button.disabled=!count}
