  if(route==='settings'&&(name in state.settingsDraft||name==='default-layout')){state.settingsDraft[name==='default-layout'?'layout':name]=name==='homeCount'?Number(value):value;const line=document.getElementById('settings-change-status');if(line)line.textContent='有尚未保存的修改，前台仍使用已保存设置。';return}
