function parseTitleFile(text,isCsv=false,includeMetadata=false){const lines=[];if(!isCsv){const titles=titleRows(text.replace(/^\uFEFF/,''));return includeMetadata?titles.map(title=>({title,scopeNote:''})):titles}let cell='',row=[],quoted=false;const source=text.replace(/^\uFEFF/,'');for(let i=0;i<source.length;i++){const ch=source[i];if(ch==='"'){if(quoted&&source[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&source[i+1]==='\n')i++;row.push(cell);cell='';if(row.some(v=>v.trim()))lines.push(row);row=[]}else cell+=ch}if(quoted)throw Error('CSV 的引号没有闭合，请检查文件或使用 TXT。');row.push(cell);if(row.some(v=>v.trim()))lines.push(row);const titleHeaders=['标题','专题标题','title','topic_title'];const scopeHeaders=['scope','scope_note','范围','适用范围','适用范围与限制'];const headers=(lines[0]||[]).map(norm);const titleIndex=headers.findIndex(v=>titleHeaders.includes(v));const scopeIndex=headers.findIndex(v=>scopeHeaders.includes(v));if(lines.some(r=>r.length!==1)&&titleIndex<0)throw Error('多列 CSV 需要“标题”表头，可选增加“适用范围与限制”列。');const width=(lines[0]||[]).length;if(lines.some(r=>r.length!==width))throw Error('CSV 每行列数应与表头一致，请检查逗号和引号。');const values=(titleIndex>=0?lines.slice(1):lines).map(row=>({title:(row[titleIndex>=0?titleIndex:0]||'').replace(/\r?\n/g,' ').trim(),scopeNote:scopeIndex>=0?(row[scopeIndex]||'').trim():''})).filter(row=>row.title);return includeMetadata?values:values.map(row=>row.title)}
document.addEventListener('change',e=>{if(!['library-file','batch-file'].includes(e.target.id)||!e.target.files?.[0])return;const file=e.target.files[0];const forLibrary=e.target.id==='library-file';const f=forLibrary?libraryForm():state.batchForm;const route=routeInfo().route;const reader=new FileReader();reader.onload=()=>{try{document.activeElement?.blur();const parsed=parseTitleFile(String(reader.result),file.name.toLowerCase().endsWith('.csv'),!forLibrary);const before=uniqueTitles(f.raw);const existing=new Set(before.map(norm));const imported=[...new Map(parsed.map(row=>[forLibrary?norm(row):topicKey(row),row])).values()];const added=forLibrary?imported.filter(title=>!existing.has(norm(title))):imported;const rows=parsed;f.raw=forLibrary?[...before,...added].join('\n'):encodeBatchRows(added);delete state.errors[forLibrary?'library-import':'batch-import'];if(routeInfo().route===route)render();notify(`读取 ${rows.length} 行标题，${forLibrary?'新增':'保留'} ${added.length} 个，重复 ${rows.length-added.length} 行。名称与其他设置保留。`)}catch(error){state.errors[forLibrary?'library-import':'batch-import']=error.message;if(routeInfo().route===route)render();notify('导入没有完成，原有标题与表单保留。')}};reader.onerror=()=>{state.errors[forLibrary?'library-import':'batch-import']='文件没有读取完成，可以重新选择，或把标题粘贴到输入框。';if(routeInfo().route===route)render()};reader.readAsText(file)});
document.addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Enter'&&['search','front-search','chat-prompt','picker-search'].includes(e.target.id)){e.preventDefault();document.querySelector(`[data-action="${e.target.id==='chat-prompt'?'chat-send':e.target.id}"]`)?.click()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){const action={new:'save',edit:'save',settings:'save-settings','library-edit':'save-library','task-new':'save-task'}[routeInfo().route];if(action){e.preventDefault();document.querySelector(`[data-action="${action}"]`)?.click()}}if(e.key==='Escape')document.getElementById('sidebar')?.classList.remove('open');if(e.key==='Enter'&&e.target.matches('[role="button"][data-action]')){e.preventDefault();e.target.click()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
render();

matchMedia('(max-width:759px)').addEventListener('change',()=>render());
